  _CeladonMartRoofLittleGirlReceivedTM49Text = "{PLAYER} received\nTM49!",
  _CeladonMartRoofLittleGirlTM13ExplanationText = "\f{RAM:wStringBuffer} contains\nICE BEAM!\fIt can freeze the\ntarget sometimes!",
  _CeladonMartRoofLittleGirlTM48ExplanationText = "\f{RAM:wStringBuffer} contains\nROCK SLIDE!\fIt can spook the\ntarget sometimes!",
  _CeladonMartRoofLittleGirlTM49ExplanationText = "\fTM49 contains\nTRI ATTACK!",
  _CeladonMartRoofLittleGirlYayFreshWaterText = "Yay!\fFRESH WATER!\fThank you!\fYou can have this\nfrom me!",
  _CeladonMartRoofLittleGirlYayLemonadeText = "Yay!\fLEMONADE!\fThank you!\fYou can have this\nfrom me!",
  _CeladonMartRoofLittleGirlYaySodaPopText = "Yay!\fSODA POP!\fThank you!\fYou can have this\nfrom me!",
  _CeladonMartRoofSuperNerdText = "My sister is a\ntrainer, believe\vit or not.\fBut, she's so\nimmature, she\vdrives me nuts!",
  _CeladonPokecenterBeautyText = "I rode uphill on\nCYCLING ROAD from\vFUCHSIA!",
  _CeladonPokecenterGentlemanText = "POKé FLUTE awakens\nPOKéMON with a\vsound that only\vthey can hear!",
  _CeruleanBadgeHouseBoulderBadgeText = "The ATTACK of all\nPOKéMON increases\va little bit.\fIt also lets you\nuse FLASH any\vtime you desire.",
  _CeruleanBadgeHouseCascadeBadgeText = "POKéMON up to L30\nwill obey you.\fAny higher, they\nbecome unruly!\fIt also lets you\nuse CUT outside\vof battle.",
  _CeruleanBadgeHouseEarthBadgeText = "All POKéMON will\nobey you!",
  _CeruleanBadgeHouseMarshBadgeText = "POKéMON up to L70\nwill obey you.\fAny higher, they\nbecome unruly!",
  _CeruleanBadgeHouseMiddleAgedManText = "POKéMON BADGEs\nare owned only by\vskilled trainers.\fI see you have\nat least one.\fThose BADGEs have\namazing secrets!",
  _CeruleanBadgeHouseMiddleAgedManVisitAnyTimeText = "Come visit me any\ntime you wish.",
  _CeruleanBadgeHouseMiddleAgedManWhichBadgeText = "Now then...\fWhich of the 8\nBADGEs should I\vdescribe?",
  _CeruleanBadgeHouseRainbowBadgeText = "POKéMON up to L50\nwill obey you.\fAny higher, they\nbecome unruly!\fIt also lets you\nuse STRENGTH out-\vside of battle.",
  _CeruleanBadgeHouseSoulBadgeText = "The DEFENSE of all\nPOKéMON increases\va little bit.\fIt also lets you\nuse SURF outside\vof battle.",
  _CeruleanBadgeHouseThunderBadgeText = "The SPEED of all\nPOKéMON increases\va little bit.\fIt also lets you\nuse FLY outside\vof battle.",
  _CeruleanBadgeHouseVolcanoBadgeText = "Your POKéMON's\nSPECIAL abilities\vincrease a bit.",
  _CeruleanCityBikeShopSign = "Grass and caves\nhandled easily!\vBIKE SHOP",
  _CeruleanCityCooltrainerF1SlowbroPunchText = "SLOWBRO punch!\nNo! You blew it\vagain!",
  _CeruleanCityCooltrainerF1SlowbroUseSonicboomText = "OK! SLOWBRO!\nUse SONICBOOM!\vCome on, SLOWBRO\vpay attention!",
  _CeruleanCityCooltrainerF1SlowbroWithdrawText = "SLOWBRO, WITHDRAW!\nNo! That's wrong!\fIt's so hard to\ncontrol POKéMON!\fYour POKéMON's\nobedience depends\von your abilities\vas a trainer!",
  _CeruleanCityCooltrainerF2Text = "I want a bright\nred BICYCLE!\fI'll keep it at\nhome, so it won't\vget dirty!",
  _CeruleanCityCooltrainerMText = "You're a trainer\ntoo? Collecting,\vfighting, it's a\vtough life.",
  _CeruleanCityGuardText = "The people here\nwere robbed.\fIt's obvious that\nTEAM ROCKET is\vbehind this most\vheinous crime!\fEven our POLICE\nforce has trouble\vwith the ROCKETs!",
  _CeruleanCityGymSign = "CERULEAN CITY\nPOKéMON GYM\vLEADER: MISTY\fThe Tomboyish\nMermaid!",
  _CeruleanCityRivalDefeatedText = "Hey!\nTake it easy!\vYou won already!",
  _CeruleanCityRivalIWentToBillsText = "{RIVAL}: Hey,\nguess what?\fI went to BILL's\nand got him to\vshow me his rare\vPOKéMON!\fThat added a lot\nof pages to my\vPOKéDEX!\fAfter all, BILL's\nworld famous as a\vPOKéMANIAC!\fHe invented the\nPOKéMON Storage\vSystem on PC!\fSince you're using\nhis system, go\vthank him!\fWell, I better\nget rolling!\vSmell ya later!",
  _CeruleanCityRivalPreBattleText = "{RIVAL}: Yo!\n{PLAYER}!\fYou're still\nstruggling along\vback here?\fI'm doing great!\nI caught a bunch\vof strong and\vsmart POKéMON!\fHere, let me see\nwhat you caught,\v{PLAYER}!",
  _CeruleanCityRivalVictoryText = "Heh!\nYou're no match\vfor my genius!",
  _CeruleanCityRocketIBetterGetMovingText = "\fI better get\nmoving! Bye!",
  _CeruleanCityRocketIGiveUpText = "Stop!\nI give up! I'll\vleave quietly!",
  _CeruleanCityRocketIllReturnTheTMText = "OK! I'll return\nthe TM I stole!",
  _CeruleanCityRocketReceivedTM28Text = "{PLAYER} recovered\nTM28!",
  _CeruleanCityRocketTM28NoRoomText = "Make room for\nthis!\fI can't run until\nI give it to you!",
  _CeruleanCityRocketText = "Hey! Stay out!\nIt's not your\vyard! Huh? Me?\fI'm an innocent\nbystander! Don't\vyou believe me?",
  _CeruleanCitySignText = "CERULEAN CITY\nA Mysterious,\vBlue Aura\vSurrounds It",
  _CeruleanCitySlowbroIgnoredOrdersText = "SLOWBRO\nignored orders...",
  _CeruleanCitySlowbroIsLoafingAroundText = "SLOWBRO is\nloafing around...",
  _CeruleanCitySlowbroTookASnoozeText = "SLOWBRO took a\nsnooze...",
  _CeruleanCitySlowbroTurnedAwayText = "SLOWBRO turned\naway...",
  _CeruleanCitySuperNerd1Text = "That bush in\nfront of the shop\vis in the way.\fThere might be a\nway around.",
  _CeruleanCitySuperNerd2Text = "You're making an\nencyclopedia on\vPOKéMON? That\vsounds amusing.",
  _CeruleanCitySuperNerd3Text = "This is CERULEAN\nCAVE! Horribly\vstrong POKéMON\vlive in there!\fThe POKéMON LEAGUE\nchampion is the\vonly person who\vis allowed in!",
  _CeruleanCityTrainerTipsText = "TRAINER TIPS\fPressing B Button\nduring evolution\vcancels the whole\vprocess.",
  _CeruleanGymAfterBattleText1 = "You have to face\nother trainers to\vfind out how good\vyou really are.",
  _CeruleanGymAfterBattleText2 = "MISTY is going to\nkeep improving!\fShe won't lose to\nsomeone like you!",
  _CeruleanGymBattleText1 = "I'm more than good\nenough for you!\fMISTY can wait!",
  _CeruleanGymBattleText2 = "Splash!\fI'm first up!\nLet's do it!",
  _CeruleanGymEndBattleText1 = "You\noverwhelmed me!",
  _CeruleanGymEndBattleText2 = "That\ncan't be!",
  _CeruleanGymGymGuideBeatMistyText = "You beat MISTY!\nWhat'd I tell ya?\fYou and me kid,\nwe make a pretty\vdarn good team!",
  _CeruleanGymGymGuideChampInMakingText = "Yo! Champ in\nmaking!\fHere's my advice!\fThe LEADER, MISTY,\nis a pro who uses\vwater POKéMON!\fYou can drain all\ntheir water with\vplant POKéMON!\fOr, zap them with\nelectricity!",
  _CeruleanGymMistyCascadeBadgeInfoText = "The CASCADEBADGE\nmakes all POKéMON\vup to L30 obey!\fThat includes\neven outsiders!\fThere's more, you\ncan now use CUT\vany time!\fYou can CUT down\nsmall bushes to\vopen new paths!\fYou can also have\nmy favorite TM!",
  _CeruleanGymMistyPreBattleText = "Hi, you're a new\nface!\fTrainers who want\nto turn pro have\vto have a policy\vabout POKéMON!\fWhat is your\napproach when you\vcatch POKéMON?\fMy policy is an\nall-out offensive\vwith water-type\vPOKéMON!",
  _CeruleanGymMistyReceivedCascadeBadgeText = "Wow!\nYou're too much!\fAll right!\fYou can have the\nCASCADEBADGE to\vshow you beat me!",
  _CeruleanGymMistyReceivedTM11Text = "{PLAYER} received\nTM11!",
  _CeruleanGymMistyTM11ExplanationText = "TM11 teaches\nBUBBLEBEAM!\fUse it on an\naquatic POKéMON!",
  _CeruleanGymMistyTM11NoRoomText = "You better make\nroom for this!",
  _CeruleanMartCooltrainerFText = "Have you seen any\nRARE CANDY?\fIt's supposed to\nmake POKéMON go\vup one level!",
  _CeruleanMartCooltrainerMText = "Use REPEL to keep\nbugs and weak\vPOKéMON away.\fPut your strongest\nPOKéMON at the\vtop of the list\vfor best results!",
  _CeruleanPokecenterGentlemanText = "Have you heard\nabout BILL?\fEveryone calls\nhim a POKéMANIAC!\fI think people\nare just jealous\vof BILL, though.\fWho wouldn't want\nto boast about\vtheir POKéMON?",
  _CeruleanPokecenterGuyText = "BILL has lots of\nPOKéMON!\fHe collects rare\nones too!",
  _CeruleanPokecenterSuperNerdText = "That BILL!\fI heard that\nhe'll do whatever\vit takes to get\vrare POKéMON!",
  _CeruleanTradeHouseGrannyText = "My husband likes\ntrading POKéMON.\fIf you are a\ncollector, would\vyou please trade\vwith him?",
  _CeruleanTrashedHouseFishingGuruTheyStoleATMText = "Those miserable\nROCKETs!\fLook what they\ndid here!\fThey stole a TM\nfor teaching\vPOKéMON how to\vDIG holes!\fThat cost me a\nbundle, it did!",
  _CeruleanTrashedHouseFishingGuruWhatsLostIsLostText = "I figure what's\nlost is lost!\fI decided to teach\nDIGLETT how to\vDIG without a TM!",
  _CeruleanTrashedHouseGirlText = "TEAM ROCKET must\nbe trying to DIG\vtheir way into no\vgood!",
  _CeruleanTrashedHouseWallHoleText = "TEAM ROCKET left\na way out!",
  _ChampionsRoomOakComeWithMeText = "OAK: {PLAYER}!\fYou understand\nthat your victory\vwas not just your\vown doing!\fThe bond you share\nwith your POKéMON\vis marvelous!\f{PLAYER}!\nCome with me!",
  _ChampionsRoomOakCongratulatesPlayerText = "OAK: So, you won!\nCongratulations!\vYou're the new\vPOKéMON LEAGUE\vchampion!\fYou've grown up so\nmuch since you\vfirst left with\v{RAM:wNameBuffer}!\f{PLAYER}, you have\ncome of age!",
  _ChampionsRoomOakDisappointedWithRivalText = "OAK: {RIVAL}! I'm\ndisappointed!\fI came when I\nheard you beat\vthe ELITE FOUR!\fBut, when I got\nhere, you had\valready lost!\f{RIVAL}! Do you\nunderstand why\vyou lost?\fYou have forgotten\nto treat your\vPOKéMON with\vtrust and love!\fWithout them, you\nwill never become\va champ again!",
  _ChampionsRoomOakText = "OAK: {PLAYER}!",
  _ChampionsRoomRivalAfterBattleText = "Why?\nWhy did I lose?\fI never made any\nmistakes raising\vmy POKéMON...\fDarn it! You're\nthe new POKéMON\vLEAGUE champion!\fAlthough I don't\nlike to admit it.",
  _ChampionsRoomRivalIntroText = "{RIVAL}: Hey!\fI was looking\nforward to seeing\vyou, {PLAYER}!\fMy rival should\nbe strong to keep\vme sharp!\fWhile working on\nPOKéDEX, I looked\vall over for\vpowerful POKéMON!\fNot only that, I\nassembled teams\vthat would beat\vany POKéMON type!\fAnd now!\fI'm the POKéMON\nLEAGUE champion!\f{PLAYER}! Do you\nknow what that\vmeans?\fI'll tell you!\fI am the most\npowerful trainer\vin the world!",
  _ChanseyDexEntry = "A rare and elusive\nPOKéMON that is\nsaid to bring\fhappiness to those\nwho manage to get\nit",
  _ChargeMoveEffectText = "{USER}",
  _CharizardDexEntry = "Spits fire that\nis hot enough to\nmelt boulders.\fKnown to cause\nforest fires\nunintentionally",
  _CharmanderDexEntry = "Obviously prefers\nhot places. When\nit rains, steam\fis said to spout\nfrom the tip of\nits tail",
  _CharmeleonDexEntry = "When it swings\nits burning tail,\nit elevates the\ftemperature to\nunbearably high\nlevels",
  _ChooseABoxText = "Choose a\nPOKéMON BOX.",
  _CinnabarGymBlainePostBattleAdviceText = "FIRE BLAST is the\nultimate fire\vtechnique!\fDon't waste it on\nwater POKéMON!",
  _CinnabarGymBlainePreBattleText = "Hah!\fI am BLAINE! I\nam the LEADER of\vCINNABAR GYM!\fMy fiery POKéMON\nwill incinerate\vall challengers!\fHah! You better\nhave BURN HEAL!",
  _CinnabarGymBlaineReceivedTM38Text = "{PLAYER} received\n{RAM:wStringBuffer}!",
  _CinnabarGymBlaineReceivedVolcanoBadgeText = "I have\nburnt out!\fYou have earned\nthe VOLCANOBADGE!",
  _CinnabarGymBlaineTM38ExplanationText = "\fTM38 contains\nFIRE BLAST!\fTeach it to fire-\ntype POKéMON!\fCHARMELEON or\nPONYTA would be\vgood bets!",
  _CinnabarGymBlaineTM38NoRoomText = "Make room for my\ngift!",
  _CinnabarGymBlaineVolcanoBadgeInfoText = "Hah!\fThe VOLCANOBADGE\nheightens the\vSPECIAL abilities\vof your POKéMON!\fHere, you can\nhave this too!",
  _CinnabarGymGymGuideBeatBlaineText = "{PLAYER}! You beat\nthat fire brand!",
  _CinnabarGymGymGuideChampInMakingText = "Yo! Champ in\nmaking!\fThe hot-headed\nBLAINE is a fire\vPOKéMON pro!\fDouse his spirits\nwith water!\fYou better take\nsome BURN HEALs!",
  _CinnabarGymQuizCorrectText = "You're absolutely\ncorrect!\fGo on through!",
  _CinnabarGymQuizIncorrectText = "Sorry! Bad call!",
  _CinnabarGymQuizIntroText = "POKéMON Quiz!\fGet it right and\nthe door opens to\vthe next room!\fGet it wrong and\nface a trainer!\fIf you want to\nconserve your\vPOKéMON for the\vGYM LEADER...\fThen get it right!\nHere we go!",
  _CinnabarGymSuperNerd1AfterBattleText = "Fire, or to be\nmore precise,\vcombustion...\fBlah, blah, blah,\nblah...",
  _CinnabarGymSuperNerd1BattleText = "Do you know how\nhot POKéMON fire\vbreath can get?",
  _CinnabarGymSuperNerd1EndBattleText = "Yow!\nHot, hot, hot!",
  _CinnabarGymSuperNerd2AfterBattleText = "I can't help\nstealing other\vpeople's POKéMON!",
  _CinnabarGymSuperNerd2BattleText = "I was a thief, but\nI became straight\vas a trainer!",
  _CinnabarGymSuperNerd2EndBattleText = "I\nsurrender!",
  _CinnabarGymSuperNerd3AfterBattleText = "My theories are\ntoo complicated\vfor you!",
  _CinnabarGymSuperNerd3BattleText = "You can't win!\nI have studied\vPOKéMON totally!",
  _CinnabarGymSuperNerd3EndBattleText = "Waah!\nMy studies!",
  _CinnabarGymSuperNerd4AfterBattleText = "I wish there was\na thief POKéMON!\vI'd use that!",
  _CinnabarGymSuperNerd4BattleText = "I just like using\nfire POKéMON!",
  _CinnabarGymSuperNerd4EndBattleText = "Too hot\nto handle!",
  _CinnabarGymSuperNerd5AfterBattleText = "BLAINE was lost\nin the mountains\vwhen a fiery bird\vPOKéMON appeared.\fIts light enabled\nBLAINE to find\vhis way down!",
  _CinnabarGymSuperNerd5BattleText = "I know why BLAINE\nbecame a trainer!",
  _CinnabarGymSuperNerd5EndBattleText = "Ow!",
  _CinnabarGymSuperNerd6AfterBattleText = "Us fire POKéMON\nfans like PONYTA\vand NINETALES!",
  _CinnabarGymSuperNerd6BattleText = "I've been to many\nGYMs, but this is\vmy favorite!",
  _CinnabarGymSuperNerd6EndBattleText = "Yowza!\nToo hot!",
  _CinnabarGymSuperNerd7AfterBattleText = "Water beats fire!\nBut, fire melts\vice POKéMON!",
  _CinnabarGymSuperNerd7BattleText = "Fire is weak\nagainst H2O!",
  _CinnabarGymSuperNerd7EndBattleText = "Oh!\nSnuffed out!",
  _CinnabarIslandDoorIsLockedText = "The door is\nlocked...",
  _CinnabarIslandGamblerText = "Scientists conduct\nexperiments in\vthe burned out\vbuilding.",
  _CinnabarIslandGirlText = "CINNABAR GYM's\nBLAINE is an odd\vman who has lived\vhere for decades.",
  _CinnabarIslandGymSignText = "CINNABAR ISLAND\nPOKéMON GYM\vLEADER: BLAINE\fThe Hot-Headed\nQuiz Master!",
  _CinnabarIslandPokemonLabSignText = "POKéMON LAB",
  _CinnabarIslandSignText = "CINNABAR ISLAND\nThe Fiery Town of\vBurning Desire",
  _CinnabarLabFishingGuruText = "We study POKéMON\nextensively here.\fPeople often bring\nus rare POKéMON\vfor examination.",
  _CinnabarLabFossilRoomScientist1ComeAgainText = "Aiyah! You come\nagain!",
  _CinnabarLabFossilRoomScientist1FossilIsBackToLifeText = "Where were you?\fYour fossil is\nback to life!\fIt was {RAM:wStringBuffer}\nlike I think!",
  _CinnabarLabFossilRoomScientist1GoForAWalkText = "I take a little\ntime!\fYou go for walk a\nlittle while!",
  _CinnabarLabFossilRoomScientist1GoForAWalkText2 = "I take a little\ntime!\fYou go for walk a\nlittle while!",
  _CinnabarLabFossilRoomScientist1NoFossilsText = "No! Is too bad!",
  _CinnabarLabFossilRoomScientist1SeesFossilText = "Oh! That is\n{RAM:wNameBuffer}!\fIt is fossil of\n{RAM:wStringBuffer}, a\vPOKéMON that is\valready extinct!\fMy Resurrection\nMachine will make\vthat POKéMON live\vagain!",
  _CinnabarLabFossilRoomScientist1TakesFossilText = "So! You hurry and\ngive me that!\f{PLAYER} handed\nover {RAM:wNameBuffer}!",
  _CinnabarLabFossilRoomScientist1Text = "Hiya!\fI am important\ndoctor!\fI study here rare\nPOKéMON fossils!\fYou! Have you a\nfossil for me?",
  _CinnabarLabMeetingRoomSignText = "POKéMON LAB\nMeeting Room",
  _CinnabarLabMetronomeRoomAmberPipeText = "An amber pipe!",
  _CinnabarLabMetronomeRoomPCText = "There's an e-mail\nmessage!\f...\fThe 3 legendary\nbird POKéMON are\vARTICUNO, ZAPDOS\vand MOLTRES.\fTheir whereabouts\nare unknown.\fWe plan to explore\nthe cavern close\vto CERULEAN.\fFrom: POKéMON\nRESEARCH TEAM\f...",
  _CinnabarLabMetronomeRoomScientist1ReceivedTM35Text = "{PLAYER} received \n{RAM:wStringBuffer}!",
  _CinnabarLabMetronomeRoomScientist1TM35ExplanationText = "Tch-tch-tch!\nThat's the sound\vof a METRONOME!\fIt tweaks your\nPOKéMON's brain\vinto using moves\vit doesn't know!",
  _CinnabarLabMetronomeRoomScientist1TM35NoRoomText = "Your pack is\ncrammed full!",
  _CinnabarLabMetronomeRoomScientist1Text = "Tch-tch-tch!\nI made a cool TM!\fIt can cause all\nkinds of fun!",
  _CinnabarLabMetronomeRoomScientist2Text = "EEVEE can evolve\ninto 1 of 3 kinds\vof POKéMON.",
  _CinnabarLabPhotoText = "A photo of the\nLAB's founder,\vDR.FUJI!",
  _CinnabarLabRAndDSignText = "POKéMON LAB\nR-and-D Room",
  _CinnabarLabTestingRoomSignText = "POKéMON LAB\nTesting Room",
  _CinnabarLabTradeRoomSuperNerdText = "I found this very\nstrange fossil in\vMT.MOON!\fI think it's a\nrare, prehistoric\vPOKéMON!",
  _CinnabarMartScientistText = "It never hurts to\nhave extra items!",
  _CinnabarMartSilphWorkerFText = "Don't they have X\nATTACK? It's good\vfor battles!",
  _CinnabarPokecenterCooltrainerFText = "You can cancel\nevolution.\fWhen a POKéMON is\nevolving, you can\vstop it and leave\vit the way it is.",
  _CinnabarPokecenterGentlemanText = "Do you have any\nfriends?\fPOKéMON you get\nin trades grow\vvery quickly.\fI think it's\nworth a try!",
  _CinnabarPokecenterGuyText = "POKéMON can still\nlearn techniques\vafter canceling\vevolution.\fEvolution can wait\nuntil new moves\vhave been learned.",
  _CinnabarQuizQuestionsText1 = "CATERPIE evolves\ninto BUTTERFREE?",
  _CinnabarQuizQuestionsText2 = "There are 9\ncertified POKéMON\vLEAGUE BADGEs?",
  _CinnabarQuizQuestionsText3 = "POLIWAG evolves 3\ntimes?",
  _CinnabarQuizQuestionsText4 = "Are thunder moves\neffective against\vground element-\vtype POKéMON?",
  _CinnabarQuizQuestionsText5 = "POKéMON of the\nsame kind and\vlevel are not\videntical?",
  _CinnabarQuizQuestionsText6 = "TM28 contains\nTOMBSTONER?",
  _ClearSaveDataText = "Clear all saved\ndata?",
  _ClefableDexEntry = "A timid fairy\nPOKéMON that is\nrarely seen. It\fwill run and hide\nthe moment it\nsenses people",
  _ClefairyDexEntry = "Its magical and\ncute appeal has\nmany admirers.\fIt is rare and\nfound only in\ncertain areas",
  _ClosedOaksPCText = "Closed link to\nPROF.OAK's PC.",
  _CloysterDexEntry = "When attacked, it\nlaunches its\nhorns in quick\fvolleys. Its\ninnards have\nnever been seen",
