  _ConvertedTypeText = "Converted type to\n{TARGET}'s!",
  _CopycatsHouse1FChanseyText = "CHANSEY: Chaan!\nSii!",
  _CopycatsHouse1FMiddleAgedManText = "My daughter likes\nto mimic people.\fHer mimicry has\nearned her the\vnickname COPYCAT\varound here!",
  _CopycatsHouse1FMiddleAgedWomanText = "My daughter is so\nself-centered.\vShe only has a\vfew friends.",
  _CopycatsHouse2FCopycatDoYouLikePokemonText = "{PLAYER}: Hi! Do\nyou like POKéMON?\f{PLAYER}: Uh no, I\njust asked you.\f{PLAYER}: Huh?\nYou're strange!\fCOPYCAT: Hmm?\nQuit mimicking?\fBut, that's my\nfavorite hobby!",
  _CopycatsHouse2FCopycatReceivedTM31Text = "{PLAYER} received\n{RAM:wStringBuffer}!",
  _CopycatsHouse2FCopycatTM31Explanation1Text = "\fTM31 contains my\nfavorite, MIMIC!\fUse it on a good\nPOKéMON!",
  _CopycatsHouse2FCopycatTM31Explanation2Text = "{PLAYER}: Hi!\nThanks for TM31!\f{PLAYER}: Pardon?\f{PLAYER}: Is it\nthat fun to mimic\vmy every move?\fCOPYCAT: You bet!\nIt's a scream!",
  _CopycatsHouse2FCopycatTM31NoRoomText = "Don't you want\nthis?",
  _CopycatsHouse2FCopycatTM31PreReceiveText = "Oh wow!\nA POKé DOLL!\fFor me?\nThank you!\fYou can have\nthis, then!",
  _CopycatsHouse2FDoduoText = "DODUO: Giiih!\fMIRROR MIRROR ON\nTHE WALL, WHO IS\vTHE FAIREST ONE\vOF ALL?",
  _CopycatsHouse2FPCCantSeeText = "Huh? Can't see!",
  _CopycatsHouse2FPCMySecretsText = "...\fMy Secrets!\fSkill: Mimicry!\nHobby: Collecting\vdolls!\vFavorite POKéMON:\vCLEFAIRY!",
  _CopycatsHouse2FRareDollText = "This is a rare\nPOKéMON! Huh?\vIt's only a doll!",
