  _NameRatersHouseNameRaterPokemonHasBeenRenamedText = "OK! This POKéMON\nhas been renamed\v{RAM:wBuffer}!\fThat's a better\nname than before!",
  _NameRatersHouseNameRaterWantMeToRateText = "Hello, hello!\nI am the official\vNAME RATER!\fWant me to rate\nthe nicknames of\vyour POKéMON?",
  _NameRatersHouseNameRaterWhatShouldWeNameItText = "Fine! What should\nwe name it?",
  _NameRatersHouseNameRaterWhichPokemonText = "Which POKéMON\nshould I look at?",
  _NeedYourPokemonText = "OK. We'll need\nyour POKéMON.",
  _NewBadgeRequiredText = "No! A new BADGE\nis required.",
  _NewBicycleText = "A shiny new\nBICYCLE!",
  _NidokingDexEntry = "It uses its\npowerful tail in\nbattle to smash,\fconstrict, then\nbreak the prey's\nbones",
  _NidoqueenDexEntry = "Its hard scales\nprovide strong\nprotection. It\fuses its hefty\nbulk to execute\npowerful moves",
  _NidoranFDexEntry = "Although small,\nits venomous\nbarbs render this\fPOKéMON dangerous.\nThe female has\nsmaller horns",
  _NidoranMDexEntry = "Stiffens its ears\nto sense danger.\nThe larger its\fhorns, the more\npowerful its\nsecreted venom",
  _NidorinaDexEntry = "The female's horn\ndevelops slowly.\nPrefers physical\fattacks such as\nclawing and\nbiting",
  _NidorinoDexEntry = "An aggressive\nPOKéMON that is\nquick to attack.\fThe horn on its\nhead secretes a\npowerful venom",
  _NinetalesDexEntry = "Very smart and\nvery vengeful.\nGrabbing one of\fits many tails\ncould result in a\n1000-year curse",
