  _NothingToDepositText = "You have nothing\nto deposit.",
  _OHKOText = "One-hit KO!",
  _OKExclamationText = "OK!",
  _OakLabEmailText = "There's an e-mail\nmessage here!\f...\fCalling all\nPOKéMON trainers!\fThe elite trainers\nof POKéMON LEAGUE\vare ready to take\von all comers!\fBring your best\nPOKéMON and see\vhow you rate as a\vtrainer!\fPOKéMON LEAGUE HQ\nINDIGO PLATEAU\fPS: PROF.OAK,\nplease visit us!\v...",
  _OakSpeechText1 = "Hello there!\nWelcome to the\vworld of POKéMON!\fMy name is OAK!\nPeople call me\vthe POKéMON PROF!",
  _OakSpeechText2A = "This world is\ninhabited by\vcreatures called\vPOKéMON!",
  _OakSpeechText2B = "\fFor some people,\nPOKéMON are\vpets. Others use\vthem for fights.\fMyself...\fI study POKéMON\nas a profession.",
  _OakSpeechText3 = "{PLAYER}!\fYour very own\nPOKéMON legend is\vabout to unfold!\fA world of dreams\nand adventures\vwith POKéMON\vawaits! Let's go!",
  _OaksAideComeBackText = "Oh. I see.\fWhen you get {NUM:hOaksAideRequirement, 1, 3}\nkinds, come back\vfor {RAM:wOaksAideRewardItemName}.",
  _OaksAideGotItemText = "{PLAYER} got the\n{RAM:wOaksAideRewardItemName}!",
  _OaksAideHereYouGoText = "Great! You have\ncaught {NUM:hOaksAideNumMonsOwned, 1, 3} kinds \vof POKéMON!\vCongratulations!\fHere you go!",
  _OaksAideHiText = "Hi! Remember me?\nI'm PROF.OAK's\vAIDE!\fIf you caught {NUM:hOaksAideRequirement, 1, 3}\nkinds of POKéMON,\vI'm supposed to\vgive you an\v{RAM:wOaksAideRewardItemName}!\fSo, {PLAYER}! Have\nyou caught at\vleast {NUM:hOaksAideRequirement, 1, 3} kinds of\vPOKéMON?",
  _OaksAideNoRoomText = "Oh! I see you\ndon't have any\vroom for the\v{RAM:wOaksAideRewardItemName}.",
  _OaksAideUhOhText = "Let's see...\nUh-oh! You have\vcaught only {NUM:hOaksAideNumMonsOwned, 1, 3}\vkinds of POKéMON!\fYou need {NUM:hOaksAideRequirement, 1, 3} kinds\nif you want the\v{RAM:wOaksAideRewardItemName}.",
  _OaksLabGirlText = "PROF.OAK is the\nauthority on\vPOKéMON!\fMany POKéMON\ntrainers hold him\vin high regard!",
  _OaksLabGivePokeballsExplanationText = "\fWhen a wild\nPOKéMON appears,\vit's fair game.\fJust throw a POKé\nBALL at it and try\nto catch it!\fThis won't always\nwork, though.\fA healthy POKéMON\ncould escape. You\vhave to be lucky!",
  _OaksLabLastMonText = "That's PROF.OAK's\nlast POKéMON!",
  _OaksLabMonEnergeticText = "This POKéMON is\nreally energetic!",
  _OaksLabOak1ComeSeeMeSometimesText = "OAK: Come see me\nsometimes.\fI want to know how\nyour POKéDEX is\vcoming along.",
  _OaksLabOak1DeliverParcelText = "OAK: Oh, {PLAYER}!\fHow is my old\nPOKéMON?\fWell, it seems to\nlike you a lot.\fYou must be\ntalented as a\vPOKéMON trainer!\fWhat? You have\nsomething for me?\f{PLAYER} delivered\nOAK's PARCEL.",
  _OaksLabOak1HowIsYourPokedexComingText = "OAK: Good to see \nyou! How is your \vPOKéDEX coming? \vHere, let me take\va look!",
  _OaksLabOak1ParcelThanksText = "\fAh! This is the\ncustom POKé BALL\vI ordered!\vThank you!",
  _OaksLabOak1PokemonAroundTheWorldText = "POKéMON around the\nworld wait for\vyou, {PLAYER}!",
  _OaksLabOak1RaiseYourYoungPokemonText = "OAK: {PLAYER},\nraise your young\vPOKéMON by making\vit fight!",
  _OaksLabOak1ReceivedPokeballsText = "OAK: You can't get\ndetailed data on\vPOKéMON by just\vseeing them.\fYou must catch\nthem! Use these\vto capture wild\vPOKéMON.\f{PLAYER} got 5\nPOKé BALLs!",
  _OaksLabOak1WhichPokemonDoYouWantText = "OAK: Now, {PLAYER},\nwhich POKéMON do\vyou want?",
  _OaksLabOak1YourPokemonCanFightText = "OAK: If a wild\nPOKéMON appears,\vyour POKéMON can\vfight against it!",
  _OaksLabOak2Text = "?",
  _OaksLabOakBePatientText = "OAK: Be patient!\n{RIVAL}, you can\vhave one too!",
  _OaksLabOakChooseMonText = "OAK: {RIVAL}?\nLet me think...\fOh, that's right,\nI told you to\vcome! Just wait!\fHere, {PLAYER}!\fThere are 3\nPOKéMON here!\fHaha!\fThey are inside\nthe POKé BALLs.\fWhen I was young,\nI was a serious\vPOKéMON trainer!\fIn my old age, I\nhave only 3 left,\vbut you can have\vone! Choose!",
  _OaksLabOakDontGoAwayYetText = "OAK: Hey! Don't go\naway yet!",
  _OaksLabOakGotPokedexText = "OAK: {PLAYER} and\n{RIVAL}! Take\vthese with you!\f{PLAYER} got\nPOKéDEX from OAK!",
  _OaksLabOakIHaveARequestText = "OAK: Oh right! I\nhave a request\vof you two.",
  _OaksLabOakMyInventionPokedexText = "On the desk there\nis my invention,\vPOKéDEX!\fIt automatically\nrecords data on\vPOKéMON you've\vseen or caught!\fIt's a hi-tech\nencyclopedia!",
  _OaksLabOakThatWasMyDreamText = "To make a complete\nguide on all the\vPOKéMON in the\vworld...\fThat was my dream!\fBut, I'm too old!\nI can't do it!\fSo, I want you two\nto fulfill my\vdream for me!\fGet moving, you\ntwo!\fThis is a great\nundertaking in\vPOKéMON history!",
  _OaksLabPokedexText = "It's encyclopedia-\nlike, but the\vpages are blank!",
  _OaksLabReceivedMonText = "{PLAYER} received\na {RAM:wNameBuffer}!",
  _OaksLabRivalAmIGreatOrWhatText = "{RIVAL}: Yeah! Am\nI great or what?",
  _OaksLabRivalFedUpWithWaitingText = "{RIVAL}: Gramps!\nI'm fed up with\vwaiting!",
  _OaksLabRivalGoAheadAndChooseText = "{RIVAL}: Heh, I\ndon't need to be\vgreedy like you!\fGo ahead and\nchoose, {PLAYER}!",
  _OaksLabRivalGrampsIsntAroundText = "{RIVAL}: Yo\n{PLAYER}! Gramps\visn't around!",
  _OaksLabRivalGrampsText = "{RIVAL}: Gramps!",
  _OaksLabRivalIPickedTheWrongPokemonText = "WHAT?\nUnbelievable!\vI picked the\vwrong POKéMON!",
  _OaksLabRivalIllTakeThisOneText = "{RIVAL}: I'll take\nthis one, then!",
  _OaksLabRivalIllTakeYouOnText = "{RIVAL}: Wait\n{PLAYER}!\vLet's check out\vour POKéMON!\fCome on, I'll take\nyou on!",
  _OaksLabRivalLeaveItAllToMeText = "{RIVAL}: Alright\nGramps! Leave it\vall to me!\f{PLAYER}, I hate to\nsay it, but I\vdon't need you!\fI know! I'll\nborrow a TOWN MAP\vfrom my sis!\fI'll tell her not\nto lend you one,\v{PLAYER}! Hahaha!",
  _OaksLabRivalMyPokemonLooksStrongerText = "{RIVAL}: My\nPOKéMON looks a\vlot stronger.",
  _OaksLabRivalReceivedMonText = "{RIVAL} received\na {RAM:wNameBuffer}!",
  _OaksLabRivalSmellYouLaterText = "{RIVAL}: Okay!\nI'll make my\vPOKéMON fight to\vtoughen it up!\f{PLAYER}! Gramps!\nSmell you later!",
  _OaksLabRivalWhatAboutMeText = "{RIVAL}: Hey!\nGramps! What\vabout me?",
  _OaksLabRivalWhatDidYouCallMeForText = "{RIVAL}: What did\nyou call me for?",
  _OaksLabScientistText = "I study POKéMON as\nPROF.OAK's AIDE.",
  _OaksLabThoseArePokeBallsText = "Those are POKé\nBALLs. They\vcontain POKéMON!",
  _OaksLabYouWantBulbasaurText = "So! You want the\nplant POKéMON,\vBULBASAUR?",
  _OaksLabYouWantCharmanderText = "So! You want the\nfire POKéMON,\vCHARMANDER?",
  _OaksLabYouWantSquirtleText = "So! You want the\nwater POKéMON,\vSQUIRTLE?",
  _OddishDexEntry = "During the day,\nit keeps its face\nburied in the\fground. At night,\nit wanders around\nsowing its seeds",
  _OhFineThenText = "Oh, fine then.",
  _OlderFileWillBeErasedText = "The older file\nwill be erased to\vsave. Okay?",
  _OmanyteDexEntry = "Although long\nextinct, in rare\ncases, it can be\fgenetically\nresurrected from\nfossils",
  _OmastarDexEntry = "A prehistoric\nPOKéMON that died\nout when its\fheavy shell made\nit impossible to\ncatch prey",
  _OnceReleasedText = "Once released,\n{RAM:wStringBuffer} is\vgone forever. OK?",
  _OneMoreGoSlotMachineText = "One more \ngo?",
  _OneTwoAndText = "1, 2 and...",
