  _PPIncreasedText = "{RAM:wStringBuffer}'s PP\nincreased.",
  _PPMaxedOutText = "{RAM:wStringBuffer}'s PP\nis maxed out.",
  _PPRestoredText = "PP was restored.",
  _PalletTownFisherText = "Technology is\nincredible!\fYou can now store\nand recall items\vand POKéMON as\vdata via PC!",
  _PalletTownGirlText = "I'm raising\nPOKéMON too!\fWhen they get\nstrong, they can\vprotect me!",
  _PalletTownOakHeyWaitDontGoOutText = "OAK: Hey! Wait!\nDon't go out!",
  _PalletTownOakItsUnsafeText = "OAK: It's unsafe!\nWild POKéMON live\vin tall grass!\fYou need your own\nPOKéMON for your\vprotection.\vI know!\fHere, come with\nme!",
  _PalletTownOaksLabSignText = "OAK POKéMON\nRESEARCH LAB",
