  _ParasDexEntry = "Burrows to suck\ntree roots. The\nmushrooms on its\fback grow by draw-\ning nutrients from\nthe bug host",
  _ParasectDexEntry = "A host-parasite\npair in which the\nparasite mushroom\fhas taken over the\nhost bug. Prefers\ndamp places",
  _ParlyzHealText = "{RAM:wNameBuffer}'s\nrid of paralysis!",
  _PartyMenuBattleText = "Bring out which\nPOKéMON?",
