  _PartyMenuSwapMonText = "Move POKéMON\nwhere?",
  _PartyMenuUseTMText = "Use TM on which\nPOKéMON?",
  _PersianDexEntry = "Although its fur\nhas many admirers,\nit is tough to\fraise as a pet\nbecause of its\nfickle meanness",
  _PewterCityCooltrainerFText = "It's rumored that\nCLEFAIRYs came\vfrom the moon!\fThey appeared \nafter MOON STONE\vfell on MT.MOON.",
  _PewterCityCooltrainerMText = "There aren't many\nserious POKéMON\vtrainers here!\fThey're all like\nBUG CATCHERs,\vbut PEWTER GYM's\vBROCK is totally\vinto it!",
  _PewterCityGymSignText = "PEWTER CITY\nPOKéMON GYM\vLEADER: BROCK\fThe Rock Solid\nPOKéMON Trainer!",
  _PewterCityMuseumSignText = "PEWTER MUSEUM\nOF SCIENCE",
  _PewterCityPokecenterGuyText = "Yawn!\fWhen JIGGLYPUFF\nsings, POKéMON\vget drowsy...\f...Me too...\nSnore...",
  _PewterCityPoliceNoticeSignText = "NOTICE!\fThieves have been\nstealing POKéMON\vfossils at MT.\vMOON! Please call\vPEWTER POLICE\vwith any info!",
