  _PewterCitySuperNerd1DidYouCheckOutMuseumText = "Did you check out\nthe MUSEUM?",
  _PewterCitySuperNerd1ItsRightHereText = "It's right here!\nYou have to pay\vto get in, but\vit's worth it!\vSee you around!",
  _PewterCitySuperNerd1WerentThoseFossilsAmazingText = "Weren't those\nfossils from MT.\vMOON amazing?",
  _PewterCitySuperNerd1YouHaveToGoText = "Really?\nYou absolutely\vhave to go!",
  _PewterCitySuperNerd2DoYouKnowWhatImDoingText = "Psssst!\nDo you know what\vI'm doing?",
  _PewterCitySuperNerd2ImSprayingRepelText = "I'm spraying REPEL\nto keep POKéMON\vout of my garden!",
  _PewterCitySuperNerd2ThatsRightText = "That's right!\nIt's hard work!",
  _PewterCityTrainerTipsText = "TRAINER TIPS\fAny POKéMON that\ntakes part in\vbattle, however\vshort, earns EXP!",
  _PewterCityYoungsterGoTakeOnBrockText = "If you have the\nright stuff, go\vtake on BROCK!",
  _PewterCityYoungsterYoureATrainerFollowMeText = "You're a trainer\nright? BROCK's\vlooking for new\vchallengers!\vFollow me!",
  _PewterGymBrockBoulderBadgeInfoText = "\fThat's an official\nPOKéMON LEAGUE\vBADGE!\fIts bearer's\nPOKéMON become\vmore powerful!\fThe technique\nFLASH can now be\vused any time!",
  _PewterGymBrockPostBattleAdviceText = "There are all\nkinds of trainers\vin the world!\fYou appear to be\nvery gifted as a\vPOKéMON trainer!\fGo to the GYM in\nCERULEAN and test\vyour abilities!",
  _PewterGymBrockPreBattleText = "I'm BROCK!\nI'm PEWTER's GYM\vLEADER!\fI believe in rock\nhard defense and\vdetermination!\fThat's why my\nPOKéMON are all\vthe rock-type!\fDo you still want\nto challenge me?\vFine then! Show\vme your best!",
  _PewterGymBrockReceivedBoulderBadgeText = "I took\nyou for granted.\fAs proof of your\nvictory, here's\vthe BOULDERBADGE!\f{PLAYER} received\nthe BOULDERBADGE!",
  _PewterGymBrockWaitTakeThisText = "Wait! Take this\nwith you!",
  _PewterGymCooltrainerMAfterBattleText = "You're pretty hot,\nbut not as hot\vas BROCK!",
  _PewterGymCooltrainerMBattleText = "Stop right there,\nkid!\fYou're still light\nyears from facing\vBROCK!",
  _PewterGymCooltrainerMEndBattleText = "Darn!\fLight years isn't\ntime! It measures\vdistance!",
  _PewterGymGuideAdviceText = "The 1st POKéMON\nout in a match is\vat the top of the\vPOKéMON LIST!\fBy changing the\norder of POKéMON,\vmatches could be\vmade easier!",
  _PewterGymGuideBeginAdviceText = "All right! Let's\nget happening!",
  _PewterGymGuideFreeServiceText = "It's a free\nservice! Let's\vget happening!",
  _PewterGymGuidePostBattleText = "Just as I thought!\nYou're POKéMON\vchamp material!",
  _PewterGymGuidePreAdviceText = "Hiya! I can tell\nyou have what it\vtakes to become a\vPOKéMON champ!\fI'm no trainer,\nbut I can tell\vyou how to win!\fLet me take you\nto the top!",
  _PewterGymReceivedTM34Text = "{PLAYER} received\nTM34!",
  _PewterGymTM34NoRoomText = "You don't have\nroom for this!",
  _PewterMartSuperNerdText = "Good things can\nhappen if you\vraise POKéMON\vdiligently, even\vthe weak ones!",
  _PewterMartYoungsterText = "A shady, old man\ngot me to buy\vthis really weird\vfish POKéMON!\fIt's totally weak\nand it cost ¥500!",
  _PewterNidoranHouseLittleBoyText = "NIDORAN sit!",
  _PewterNidoranHouseMiddleAgedManText = "Our POKéMON's an\noutsider, so it's\vhard to handle.\fAn outsider is a\nPOKéMON that you\vget in a trade.\fIt grows fast, but\nit may ignore an\vunskilled trainer\vin battle!\fIf only we had\nsome BADGEs...",
  _PewterNidoranHouseNidoranText = "NIDORAN: Bowbow!",
  _PewterPokecenterGentlemanText = "What!?\fTEAM ROCKET is\nat MT.MOON? Huh?\vI'm on the phone!\fScram!",
  _PewterPokecenterJigglypuffText = "JIGGLYPUFF: Puu\npupuu!",
  _PewterSpeechHouseGamblerText = "POKéMON learn new\ntechniques as\vthey grow!\fBut, some moves\nmust be taught by\vthe trainer!",
  _PewterSpeechHouseYoungsterText = "POKéMON become\neasier to catch\vwhen they are\vhurt or asleep!\fBut, it's not a\nsure thing!",
  _PickUpPayDayMoneyText = "{PLAYER} picked up\n¥{NUM:wTotalPayDayMoney, 3 | LEADING_ZEROES | LEFT_ALIGN}!",
  _PidgeotDexEntry = "When hunting, it\nskims the surface\nof water at high\fspeed to pick off\nunwary prey such\nas MAGIKARP",
  _PidgeottoDexEntry = "Very protective\nof its sprawling\nterritorial area,\fthis POKéMON will\nfiercely peck at\nany intruder",
  _PidgeyDexEntry = "A common sight in\nforests and woods.\nIt flaps its\fwings at ground\nlevel to kick up\nblinding sand",
  _PikachuDexEntry = "When several of\nthese POKéMON\ngather, their\felectricity could\nbuild and cause\nlightning storms",
  _PinsirDexEntry = "If it fails to\ncrush the victim\nin its pincers,\fit will swing it\naround and toss\nit hard",
  _PlaySlotMachineText = "A slot machine!\nWant to play?",
  _PlayedFluteHadEffectText = "{PLAYER} played the\nPOKé FLUTE.",
  _PlayedFluteNoEffectText = "Played the POKé\nFLUTE.\fNow, that's a\ncatchy tune!",
