  _PoisonedText = "{TARGET}\nwas poisoned!",
  _PokeCenterSignText = "Heal Your POKéMON!\nPOKéMON CENTER",
  _PokemartAnythingElseText = "Is there anything\nelse I can do?",
  _PokemartBoughtItemText = "Here you are!\nThank you!",
  _PokemartBuyingGreetingText = "Take your time.",
  _PokemartGreetingText = "Hi there!\nMay I help you?",
  _PokemartItemBagEmptyText = "You don't have\nanything to sell.",
  _PokemartItemBagFullText = "You can't carry\nany more items.",
  _PokemartNotEnoughMoneyText = "You don't have\nenough money.",
  _PokemartTellBuyPriceText = "{RAM:wStringBuffer}?\nThat will be\v¥{NUM:hMoney, 3 | LEADING_ZEROES | LEFT_ALIGN}. OK?",
  _PokemartTellSellPriceText = "I can pay you\n¥{NUM:hMoney, 3 | LEADING_ZEROES | LEFT_ALIGN} for that.",
  _PokemartThankYouText = "Thank you!",
  _PokemartUnsellableItemText = "I can't put a\nprice on that.",
  _PokemonBooksText = "Crammed full of\nPOKéMON books!",
  _PokemonCenterFarewellText = "We hope to see\nyou again!",
  _PokemonCenterWelcomeText = "Welcome to our\nPOKéMON CENTER!\fWe heal your\nPOKéMON back to\vperfect health!",
  _PokemonFaintedText = "{RAM:wNameBuffer}\nfainted!",
  _PokemonFanClubBagFullText = "Make room for\nthis!",
  _PokemonFanClubChairFinalText = "Hello, {PLAYER}!\fDid you come see\nme about my\vPOKéMON again?\fNo? Too bad!",
  _PokemonFanClubChairmanIntroText = "I chair the\nPOKéMON Fan Club!\fI have collected\nover 100 POKéMON!\fI'm very fussy\nwhen it comes to\vPOKéMON!\fSo...\fDid you come\nvisit to hear\vabout my POKéMON?",
  _PokemonFanClubChairmanStoryText = "Good!\nThen listen up!\fMy favorite\nRAPIDASH...\fIt...cute...\nlovely...smart...\vplus...amazing...\vyou think so?...\voh yes...it...\vstunning...\vkindly...\vlove it!\fHug it...when...\vsleeping...warm\vand cuddly...\vspectacular...\vravishing...\v...Oops! Look at\vthe time! I kept\vyou too long!\fThanks for hearing\nme out! I want\vyou to have this!",
  _PokemonFanClubExplainBikeVoucherText = "\fExchange that for\na BICYCLE!\fDon't worry, my\nFEAROW will FLY\vme anywhere!\fSo, I don't need a\nBICYCLE!\fI hope you like\ncycling!",
  _PokemonFanClubNoStoryText = "Oh. Come back\nwhen you want to\vhear my story!",
  _PokemonFanClubPikachuFanBetterText = "Humph! My PIKACHU\nis twice as cute\vas that one!",
  _PokemonFanClubPikachuFanNormalText = "Won't you admire\nmy PIKACHU's\vadorable tail?",
  _PokemonFanClubPikachuText = "PIKACHU: Chu!\nPikachu!",
  _PokemonFanClubReceivedBikeVoucherText = "{PLAYER} received\na {RAM:wStringBuffer}!",
  _PokemonFanClubReceptionistText = "Our Chairman is\nvery vocal about\vPOKéMON.",
  _PokemonFanClubSeelFanBetterText = "Oh dear!\fMy SEEL is far\nmore attractive!",
  _PokemonFanClubSeelFanNormalText = "I just love my\nSEEL!\fIt squeals when I\nhug it!",
  _PokemonFanClubSeelText = "SEEL: Kyuoo!",
  _PokemonFanClubSign1Text = "Let's all listen\npolitely to other\vtrainers!",
  _PokemonFanClubSign2Text = "If someone brags,\nbrag right back!",
  _PokemonFightingFitText = "Thank you!\nYour POKéMON are\vfighting fit!",
  _PokemonMansion1FScientistAfterBattleText = "A key? I don't\nknow what you're\vtalking about.",
  _PokemonMansion1FScientistBattleText = "Who are you? There\nshouldn't be\vanyone here.",
  _PokemonMansion1FScientistEndBattleText = "Ouch!",
  _PokemonMansion1FSwitchNotPressedText = "Not quite yet!",
  _PokemonMansion1FSwitchPressedText = "Who wouldn't?",
  _PokemonMansion1FSwitchText = "A secret switch!\fPress it?",
  _PokemonMansion2FDiary1Text = "Diary: July 5\nGuyana,\vSouth America\fA new POKéMON was\ndiscovered deep\vin the jungle.",
  _PokemonMansion2FDiary2Text = "Diary: July 10\nWe christened the\vnewly discovered\vPOKéMON, MEW.",
  _PokemonMansion2FSuperNerdAfterBattleText = "Switches open and\nclose alternating\vsets of doors!",
  _PokemonMansion2FSuperNerdBattleText = "I can't get out!\nThis old place is\vone big puzzle!",
  _PokemonMansion2FSuperNerdEndBattleText = "Oh no!\nMy bag of loot!",
  _PokemonMansion2FSwitchNotPressedText = "Not quite yet!",
  _PokemonMansion2FSwitchPressedText = "Who wouldn't?",
  _PokemonMansion2FSwitchText = "A secret switch!\fPress it?",
  _PokemonMansion3FDiaryText = "Diary: Feb. 6\nMEW gave birth.\fWe named the\nnewborn MEWTWO.",
  _PokemonMansion3FScientistAfterBattleText = "So, you're stuck?\nTry jumping off\vover there!",
  _PokemonMansion3FScientistBattleText = "My mentor once\nlived here.",
  _PokemonMansion3FScientistEndBattleText = "Whew!\nOverwhelming!",
  _PokemonMansion3FSuperNerdAfterBattleText = "I wonder where\nmy partner went.",
  _PokemonMansion3FSuperNerdBattleText = "This place is\nlike, huge!",
  _PokemonMansion3FSuperNerdEndBattleText = "Ayah!",
  _PokemonMansionB1FBurglarAfterBattleText = "You can find stuff\nlying around.",
  _PokemonMansionB1FBurglarBattleText = "Uh-oh. Where am\nI now?",
  _PokemonMansionB1FBurglarEndBattleText = "Awooh!",
  _PokemonMansionB1FDiaryText = "Diary; Sept. 1\nMEWTWO is far too\vpowerful.\fWe have failed to\ncurb its vicious\vtendencies...",
  _PokemonMansionB1FScientistAfterBattleText = "I like it here!\nIt's conducive to\vmy studies!",
  _PokemonMansionB1FScientistBattleText = "This place is\nideal for a lab.",
  _PokemonMansionB1FScientistEndBattleText = "What\nwas that for?",
  _PokemonSellingGreetingText = "What would you\nlike to sell?",
  _PokemonStuffText = "Wow! Tons of\nPOKéMON stuff!",
  _PokemonTower1FBaldingGuyText = "I came to pray\nfor my CLEFAIRY.\fSniff! I can't\nstop crying...",
  _PokemonTower1FChannelerText = "I am a CHANNELER!\nThere are spirits\vup to mischief!",
  _PokemonTower1FGirlText = "My GROWLITHE...\nWhy did you die?",
  _PokemonTower1FMiddleAgedWomanText = "Did you come to\npay respects?\vBless you!",
  _PokemonTower1FReceptionistText = "POKéMON TOWER was\nerected in the\vmemory of POKéMON\vthat had died.",
  _PokemonTower2FChannelerText = "Even we could not\nidentify the\vwayward GHOSTs!\fA SILPH SCOPE\nmight be able to\vunmask them.",
  _PokemonTower2FRivalDefeatedText = "What?\nYou stinker!\fI took it easy on\nyou too!",
  _PokemonTower2FRivalHowsYourDexText = "How's your POKéDEX\ncoming, pal?\vI just caught a\vCUBONE!\fI can't find the\ngrown-up MAROWAK\vyet!\fI doubt there are\nany left! Well, I\vbetter get going!\vI've got a lot to\vaccomplish, pal!\fSmell ya later!",
  _PokemonTower2FRivalVictoryText = "{RIVAL}: Well,\nlook at all your\vwimpy POKéMON!\fToughen them up a\nbit more!",
  _PokemonTower2FRivalWhatBringsYouHereText = "{RIVAL}: Hey,\n{PLAYER}! What\vbrings you here?\vYour POKéMON\vdon't look dead!\fI can at least\nmake them faint!\vLet's go, pal!",
  _PokemonTower3FChanneler1AfterBattleText = "The GHOSTs can be\nidentified by the\vSILPH SCOPE.",
  _PokemonTower3FChanneler1BattleText = "Urrg...Awaa...\nHuhu...graa..",
  _PokemonTower3FChanneler1EndBattleText = "Hwa!\nI'm saved!",
  _PokemonTower3FChanneler2AfterBattleText = "Sorry! I was\npossessed!",
  _PokemonTower3FChanneler2BattleText = "Kekeke....\nKwaaah!",
  _PokemonTower3FChanneler2EndBattleText = "Hmm?\nWhat am I doing?",
  _PokemonTower3FChanneler3AfterBattleText = "My friends were\npossessed too!",
  _PokemonTower3FChanneler3BattleText = "Be gone!\nEvil spirit!",
  _PokemonTower3FChanneler3EndBattleText = "Whew!\nThe spirit left!",
  _PokemonTower4FChanneler1AfterBattleText = "I must have been\ndreaming...",
  _PokemonTower4FChanneler1BattleText = "GHOST! No!\nKwaaah!",
  _PokemonTower4FChanneler1EndBattleText = "Where\nis the GHOST?",
  _PokemonTower4FChanneler2AfterBattleText = "We can't crack\nthe identity of\vthe GHOSTs.",
  _PokemonTower4FChanneler2BattleText = "Be cursed with\nme! Kwaaah!",
  _PokemonTower4FChanneler2EndBattleText = "What!",
  _PokemonTower4FChanneler3AfterBattleText = "May the departed\nsouls of POKéMON\vrest in peace...",
  _PokemonTower4FChanneler3BattleText = "Huhuhu...\nBeat me not!",
  _PokemonTower4FChanneler3EndBattleText = "Huh?\nWho? What?",
  _PokemonTower5FChanneler1Text = "Come, child! I\nsealed this space\vwith white magic!\fYou can rest here!",
  _PokemonTower5FChanneler2AfterBattleText = "I was under\npossession!",
  _PokemonTower5FChanneler2BattleText = "Give...me...\nyour...soul...",
  _PokemonTower5FChanneler2EndBattleText = "Gasp!",
  _PokemonTower5FChanneler3AfterBattleText = "I was possessed!",
  _PokemonTower5FChanneler3BattleText = "You...shall...\njoin...us...",
  _PokemonTower5FChanneler3EndBattleText = "What\na nightmare!",
  _PokemonTower5FChanneler4AfterBattleText = "I regained my\nsenses!",
  _PokemonTower5FChanneler4BattleText = "Zombies!",
  _PokemonTower5FChanneler4EndBattleText = "Ha?",
  _PokemonTower5FChanneler5AfterBattleText = "I fell to evil\nspirits despite\vmy training!",
  _PokemonTower5FChanneler5BattleText = "Urgah...\nUrff....",
  _PokemonTower5FChanneler5EndBattleText = "Whoo!",
  _PokemonTower5FPurifiedZoneText = "Entered purified,\nprotected zone!\f{PLAYER}'s POKéMON\nare fully healed!",
  _PokemonTower6FBeGoneText = "Be gone...\nIntruders...",
  _PokemonTower6FChanneler1AfterBattleText = "I feel anemic and\nweak...",
  _PokemonTower6FChanneler1BattleText = "Give...me...\nblood...",
  _PokemonTower6FChanneler1EndBattleText = "Groan!",
  _PokemonTower6FChanneler2AfterBattleText = "Hair didn't fall\nout! It was an\vevil spirit!",
  _PokemonTower6FChanneler2BattleText = "Urff... Kwaah!",
  _PokemonTower6FChanneler2EndBattleText = "Some-\nthing fell out!",
  _PokemonTower6FChanneler3AfterBattleText = "What's going on\nhere?",
  _PokemonTower6FChanneler3BattleText = "Ke..ke...ke...\nke..ke...ke!!",
  _PokemonTower6FChanneler3EndBattleText = "Keee!",
  _PokemonTower6FGhostWasCubonesMotherText = "The GHOST was the\nrestless soul of\vCUBONE's mother!",
  _PokemonTower6FSoulWasCalmedText = "The mother's soul\nwas calmed.\fIt departed to\nthe afterlife!",
  _PokemonTower7FMrFujiRescueText = "MR.FUJI: Heh? You\ncame to save me?\fThank you. But, I\ncame here of my\vown free will.\fI came to calm\nthe soul of\vCUBONE's mother.\fI think MAROWAK's\nspirit has gone\vto the afterlife.\fI must thank you\nfor your kind\vconcern!\fFollow me to my\nhome, POKéMON\vHOUSE at the foot\vof this tower.",
  _PokemonTower7FRocket1AfterBattleText = "I'm not going to\nforget this!",
  _PokemonTower7FRocket1BattleText = "What do you want?\nWhy are you here?",
  _PokemonTower7FRocket1EndBattleText = "I give up!",
  _PokemonTower7FRocket2AfterBattleText = "POKéMON are only\ngood for making\vmoney!\fStay out of our\nbusiness!",
  _PokemonTower7FRocket2BattleText = "This old guy came\nand complained\vabout us harming\vuseless POKéMON!\fWe're talking it\nover as adults!",
  _PokemonTower7FRocket2EndBattleText = "Please!\nNo more!",
  _PokemonTower7FRocket3AfterBattleText = "You're not getting\naway with this!",
  _PokemonTower7FRocket3BattleText = "You're not saving\nanyone, kid!",
  _PokemonTower7FRocket3EndBattleText = "Don't\nfight us ROCKETs!",
  _PoliwagDexEntry = "Its newly grown\nlegs prevent it\nfrom running. It\fappears to prefer\nswimming than\ntrying to stand",
  _PoliwhirlDexEntry = "Capable of living\nin or out of\nwater. When out\fof water, it\nsweats to keep\nits body slimy",
  _PoliwrathDexEntry = "An adept swimmer\nat both the front\ncrawl and breast\fstroke. Easily\novertakes the best\nhuman swimmers",
  _PonytaDexEntry = "Its hooves are 10\ntimes harder than\ndiamonds. It can\ftrample anything\ncompletely flat\nin little time",
  _PoofText = " Poof!",
  _PorygonDexEntry = "A POKéMON that\nconsists entirely\nof programming\fcode. Capable of\nmoving freely in\ncyberspace",
  _PotionText = "{RAM:wNameBuffer}\nrecovered by {NUM:wHPBarHPDifference, 2, 3}!",
  _PowerPlantVoltorbBattleText = "Bzzzt!",
  _PowerPlantZapdosBattleText = "Gyaoo!",
  _PrimeapeDexEntry = "Always furious\nand tenacious to\nboot. It will not\fabandon chasing\nits quarry until\nit is caught",
  _PsyduckDexEntry = "While lulling its\nenemies with its\nvacant look, this\fwily POKéMON will\nuse psychokinetic\npowers",
  _PushStartText = "Push START to\nopen the MENU!",
  _RaichuDexEntry = "Its long tail\nserves as a\nground to protect\fitself from its\nown high voltage\npower",
  _RaisePPWhichTechniqueText = "Raise PP of which\ntechnique?",
  _RanAwayScaredText = "{TARGET}\nran away scared!",
  _RanFromBattleText = "{USER}\nran from battle!",
  _RapidashDexEntry = "Very competitive,\nthis POKéMON will\nchase anything\fthat moves fast\nin the hopes of\nracing it",
  _RareCandyText = "{RAM:wNameBuffer} grew\nto level {NUM:wCurEnemyLevel, 1, 3}!",
  _RaticateDexEntry = "It uses its whis-\nkers to maintain\nits balance.\fIt apparently\nslows down if\nthey are cut off",
  _RattataDexEntry = "Bites anything\nwhen it attacks.\nSmall and very\fquick, it is a\ncommon sight in\nmany places",
  _RedBedroomSNESText = "{PLAYER} is\nplaying the SNES!\v...Okay!\vIt's time to go!",
  _RedsHouse1FMomLookingGreatText = "MOM: Oh good!\nYou and your\vPOKéMON are\vlooking great!\vTake care now!",
  _RedsHouse1FMomWakeUpText = "MOM: Right.\nAll boys leave\vhome some day.\vIt said so on TV.\fPROF.OAK, next\ndoor, is looking\vfor you.",
  _RedsHouse1FMomYouShouldRestText = "MOM: {PLAYER}!\nYou should take a\vquick rest.",
  _RedsHouse1FTVStandByMeMovieText = "There's a movie\non TV. Four boys\vare walking on\vrailroad tracks.\fI better go too.",
  _RedsHouse1FTVWrongSideText = "Oops, wrong side.",
  _ReflectGainedArmorText = "{USER}\ngained armor!",
  _RegainedHealthText = "{USER}\nregained health!",
  _ReleaseWhichMonText = "Release which\nPOKéMON?",
  _RepelWoreOffText = "REPEL's effect\nwore off.",
  _RequireCoinCaseText = "A COIN CASE is\nrequired!",
  _RestorePPWhichTechniqueText = "Restore PP of\nwhich technique?",
  _ReviveText = "{RAM:wNameBuffer}\nis revitalized!",
  _RhydonDexEntry = "Protected by an\narmor-like hide,\nit is capable of\fliving in molten\nlava of 3,600\ndegrees",
  _RhyhornDexEntry = "Its massive bones\nare 1000 times\nharder than human\fbones. It can\neasily knock a\ntrailer flying",
  _Rival1WinText = "{RIVAL}: Yeah! Am\nI great or what?",
  _RivalDefeatedText = "NO!\nThat can't be!\vYou beat my best!\fAfter all that\nwork to become\vLEAGUE champ?\fMy reign is over\nalready?\vIt's not fair!",
  _RivalVictoryText = "Hahaha!\nI won, I won!\fI'm too good for\nyou, {PLAYER}!\fYou did well to\neven reach me,\v{RIVAL}, the\vPOKéMON genius!\fNice try, loser!\nHahaha!",
  _RockTunnel1FCooltrainerF1AfterBattleText = "I saw a MACHOP\nin this tunnel!",
  _RockTunnel1FCooltrainerF1BattleText = "Eek! Don't try\nanything funny in\vthe dark!",
  _RockTunnel1FCooltrainerF1EndBattleText = "It\nwas too dark!",
  _RockTunnel1FCooltrainerF2AfterBattleText = "You looked cute\nand harmless!",
  _RockTunnel1FCooltrainerF2BattleText = "I came this far\nfor POKéMON!",
  _RockTunnel1FCooltrainerF2EndBattleText = "I'm\nout of POKéMON!",
  _RockTunnel1FCooltrainerF3AfterBattleText = "Whew! I'm all\nsweaty now!",
  _RockTunnel1FCooltrainerF3BattleText = "You have POKéMON!\nLet's start!",
  _RockTunnel1FCooltrainerF3EndBattleText = "You\nplay hard!",
  _RockTunnel1FHiker1AfterBattleText = "Watch for ONIX!\nIt can put the\vsqueeze on you!",
  _RockTunnel1FHiker1BattleText = "This tunnel goes\na long way, kid!",
  _RockTunnel1FHiker1EndBattleText = "Doh!\nYou win!",
  _RockTunnel1FHiker2AfterBattleText = "That sleeping\nPOKéMON on ROUTE\v12 forced me to\vtake this detour.",
  _RockTunnel1FHiker2BattleText = "Hmm. Maybe I'm\nlost in here...",
  _RockTunnel1FHiker2EndBattleText = "Ease up!\nWhat am I doing?\vWhich way is out?",
  _RockTunnel1FHiker3AfterBattleText = "You're talented\nenough to hike!",
  _RockTunnel1FHiker3BattleText = "Outsiders like\nyou need to show\vme some respect!",
  _RockTunnel1FHiker3EndBattleText = "I give!",
  _RockTunnel1FSignText = "ROCK TUNNEL\nCERULEAN CITY -\vLAVENDER TOWN",
  _RockTunnel1FSuperNerdAfterBattleText = "Oh well, I'll get\na ZUBAT as I go!",
  _RockTunnel1FSuperNerdBattleText = "POKéMON fight!\nReady, go!",
  _RockTunnel1FSuperNerdEndBattleText = "Game\nover!",
  _RockTunnelB1FCooltrainerF1AfterBattleText = "I want to go \nhome!",
  _RockTunnelB1FCooltrainerF1BattleText = "Hikers leave twigs\nas trail markers.",
  _RockTunnelB1FCooltrainerF1EndBattleText = "Ohhh!\nI did my best!",
  _RockTunnelB1FCooltrainerF2AfterBattleText = "I like tiny\nPOKéMON, big ones\vare too scary!",
  _RockTunnelB1FCooltrainerF2BattleText = "I don't often\ncome here, but I\vwill fight you.",
  _RockTunnelB1FCooltrainerF2EndBattleText = "Oh!\nI lost!",
  _RockTunnelB1FHiker1AfterBattleText = "I go for power\nbecause I hate\vthinking!",
  _RockTunnelB1FHiker1BattleText = "Hahaha! Can you\nbeat my power?",
  _RockTunnelB1FHiker1EndBattleText = "Oops!\nOut-muscled!",
  _RockTunnelB1FHiker2AfterBattleText = "In mountains,\nyou'll often find\vrock-type POKéMON.",
  _RockTunnelB1FHiker2BattleText = "My POKéMON\ntechniques will\vleave you crying!",
  _RockTunnelB1FHiker2EndBattleText = "I give!\nYou're a better\vtechnician!",
  _RockTunnelB1FHiker3AfterBattleText = "I'll raise my\nPOKéMON to beat\vyours, kid!",
  _RockTunnelB1FHiker3BattleText = "Hit me with your\nbest shot!",
  _RockTunnelB1FHiker3EndBattleText = "Fired\naway!",
  _RockTunnelB1FSuperNerd1AfterBattleText = "When you finish\nyour POKéDEX, can\vI have it?",
  _RockTunnelB1FSuperNerd1BattleText = "You have a\nPOKéDEX?\vI want one too!",
  _RockTunnelB1FSuperNerd1EndBattleText = "Shoot!\nI'm so jealous!",
  _RockTunnelB1FSuperNerd2AfterBattleText = "Costume players\ndress up as\vPOKéMON for fun.",
  _RockTunnelB1FSuperNerd2BattleText = "Do you know about\ncostume players?",
  _RockTunnelB1FSuperNerd2EndBattleText = "Well,\nthat's that.",
  _RockTunnelB1FSuperNerd3AfterBattleText = "I'm an artist,\nnot a fighter.",
  _RockTunnelB1FSuperNerd3BattleText = "I draw POKéMON\nwhen I'm home.",
  _RockTunnelB1FSuperNerd3EndBattleText = "Whew!\nI'm exhausted!",
  _RockTunnelPokecenterFisherText = "I sold a useless\nNUGGET for ¥5000!",
  _RockTunnelPokecenterGentlemanText = "The element types\nof POKéMON make\vthem stronger\vthan some types\vand weaker than\vothers!",
  _RockTunnelPokecenterGuyText = "I heard that\nGHOSTs haunt\vLAVENDER TOWN!",
  _RocketHide3AfterBattleText3 = "Go ahead and go!\nBut, you need the\vLIFT KEY to run\vthe elevator!",
  _RocketHideout3BattleText = "We got word from\nupstairs that you\vwere coming!",
  _RocketHideout3EndBattleText3 = "What?\nI lost? No!",
  _RocketHideoutB1FRocket1AfterBattleText = "Are you dissing\nTEAM ROCKET?",
  _RocketHideoutB1FRocket1BattleText = "Who are you? How\ndid you get here?",
  _RocketHideoutB1FRocket1EndBattleText = "Oww!\nBeaten!",
  _RocketHideoutB1FRocket2AfterBattleText = "You're not going\nto get away with\vthis, brat!",
  _RocketHideoutB1FRocket2BattleText = "You broke into\nour operation?",
  _RocketHideoutB1FRocket2EndBattleText = "Burnt!",
  _RocketHideoutB1FRocket3AfterBattleText = "SILPH SCOPE?\nI don't know\vwhere it is!",
  _RocketHideoutB1FRocket3BattleText = "Intruder alert!",
  _RocketHideoutB1FRocket3EndBattleText = "I\ncan't do it!",
  _RocketHideoutB1FRocket4AfterBattleText = "OK, I'll talk!\nTake the elevator\vto see my BOSS!",
  _RocketHideoutB1FRocket4BattleText = "Why did you come\nhere?",
  _RocketHideoutB1FRocket4EndBattleText = "This\nwon't do!",
  _RocketHideoutB1FRocket5AfterBattleText = "Uh-oh, that fight\nopened the door!",
  _RocketHideoutB1FRocket5BattleText = "Are you lost, you\nlittle rat?",
  _RocketHideoutB1FRocket5EndBattleText = "Why...?",
  _RocketHideoutB2FRocketAfterBattleText = "The TEAM ROCKET\nHQ has 4 basement\vfloors. Can you\vreach the BOSS?",
  _RocketHideoutB2FRocketBattleText = "BOSS said you can\nsee GHOSTs with\vthe SILPH SCOPE!",
  _RocketHideoutB2FRocketEndBattleText = "I\nsurrender!",
  _RocketHideoutB3FRocket1AfterBattleText = "SILPH SCOPE?\nThe machine the\vBOSS stole. It's\vhere somewhere.",
  _RocketHideoutB3FRocket1BattleText = "Stop meddling in\nTEAM ROCKET's\vaffairs!",
  _RocketHideoutB3FRocket1EndBattleText = "Oof!\nTaken down!",
  _RocketHideoutB4FGiovanniHopeWeMeetAgainText = "I see that you\nraise POKéMON\vwith utmost care.\fA child like you\nwould never\vunderstand what I\vhope to achieve.\fI shall step\naside this time!\fI hope we meet\nagain...",
  _RocketHideoutB4FGiovanniImpressedYouGotHereText = "So! I must say, I\nam impressed you\vgot here!",
