  _Route8SuperNerd1EndBattleText = "Ow!\nMeltdown!",
  _Route8SuperNerd2AfterBattleText = "Go with GRIMER\nfirst...and...\v...and...then...",
  _Route8SuperNerd2BattleText = "You need strategy\nto win at this!",
  _Route8SuperNerd2EndBattleText = "It's\nnot logical!",
  _Route8SuperNerd3AfterBattleText = "We're stuck here\nbecause of the\vgates at SAFFRON.",
  _Route8SuperNerd3BattleText = "School is fun, but\nso are POKéMON.",
  _Route8SuperNerd3EndBattleText = "I'll\nstay with school.",
  _Route8UndergroundSignText = "UNDERGROUND PATH\nCELADON CITY -\vLAVENDER TOWN",
  _Route9CooltrainerF1AfterBattleText = "You need light to\nget through that\vdark tunnel ahead.",
  _Route9CooltrainerF1BattleText = "You have POKéMON\nwith you!\vYou're mine!",
  _Route9CooltrainerF1EndBattleText = "You\ndeceived me!",
  _Route9CooltrainerF2AfterBattleText = "You're obviously\ntalented! Good\vluck to you!",
  _Route9CooltrainerF2BattleText = "Don't you dare\ncondescend me!",
  _Route9CooltrainerF2EndBattleText = "No!\nYou're too much!",
  _Route9CooltrainerM1AfterBattleText = "Keep walking!",
  _Route9CooltrainerM1BattleText = "Who's that walking\nwith those good\vlooking POKéMON?",
  _Route9CooltrainerM1EndBattleText = "Out\nlike a light!",
  _Route9CooltrainerM2AfterBattleText = "Are you off to\nROCK TUNNEL too?",
  _Route9CooltrainerM2BattleText = "I'm taking ROCK\nTUNNEL to go to\vLAVENDER...",
  _Route9CooltrainerM2EndBattleText = "Can't\nmeasure up!",
  _Route9Hiker1AfterBattleText = "You sure had guts\nstanding up to me\vthere, eh?",
  _Route9Hiker1BattleText = "Bwahaha!\nGreat! I was\vbored, eh!",
  _Route9Hiker1EndBattleText = "Keep it\ncoming, eh!\fOh wait. I'm out\nof POKéMON!",
  _Route9Hiker2AfterBattleText = "Hahaha! Kids\nshould be tough!",
  _Route9Hiker2BattleText = "Hahaha!\nAren't you a\vlittle toughie!",
  _Route9Hiker2EndBattleText = "What's\nthat?",
  _Route9Hiker3AfterBattleText = "Hahahaha!\nUs hearty guys\valways laugh!",
  _Route9Hiker3BattleText = "Hahahaha!\nCome on, dude!",
  _Route9Hiker3EndBattleText = "Hahahaha!\nYou beat me fair!",
  _Route9SignText = "ROUTE 9\nCERULEAN CITY-\vROCK TUNNEL",
  _Route9Youngster1AfterBattleText = "I have to collect\nmore than bugs to\vget stronger...",
  _Route9Youngster1BattleText = "I got up early\nevery day to\vraise my POKéMON\vfrom cocoons!",
  _Route9Youngster1EndBattleText = "WHAT?\fWhat a total\nwaste of time!",
  _Route9Youngster2AfterBattleText = "If you don't like\nbug POKéMON, you\vbug me!",
  _Route9Youngster2BattleText = "Go, my super bug\nPOKéMON!",
  _Route9Youngster2EndBattleText = "My\nbugs...",
  _SSAnne1FRoomsCooltrainerFAfterBattleText = "You hurt my poor\nworldly POKéMON!\fI demand that you\nheal them at a\vPOKéMON CENTER!",
  _SSAnne1FRoomsCooltrainerFBattleText = "I collected these\nPOKéMON from all\varound the world!",
  _SSAnne1FRoomsCooltrainerFEndBattleText = "Oh no!\nI went around the\vworld for these!",
  _SSAnne1FRoomsGentleman1AfterBattleText = "You should be\nnice to friends!",
  _SSAnne1FRoomsGentleman1BattleText = "I travel alone\non my journeys!\fMy POKéMON are my\nonly friends!",
  _SSAnne1FRoomsGentleman1EndBattleText = "My, my\nfriends...",
  _SSAnne1FRoomsGentleman2AfterBattleText = "I wish to be left\nalone! Get out!",
  _SSAnne1FRoomsGentleman2BattleText = "You pup! How dare\nyou barge in!",
  _SSAnne1FRoomsGentleman2EndBattleText = "Humph!\nYou rude child!",
  _SSAnne1FRoomsGentleman3Text = "Ssh! I'm a GLOBAL\nPOLICE agent!\fI'm on the trail\nof TEAM ROCKET!",
  _SSAnne1FRoomsGirl1Text = "Waiter, I would\nlike a cherry pie\vplease!",
  _SSAnne1FRoomsGirl2Text = "We are cruising\naround the world.",
  _SSAnne1FRoomsLittleGirlText = "I always travel\nwith WIGGLYTUFF!",
  _SSAnne1FRoomsMiddleAgedManText = "A cruise is so\nelegant yet cozy!",
  _SSAnne1FRoomsWigglytuffText = "WIGGLYTUFF: Puup\npupuu!",
  _SSAnne1FRoomsYoungsterAfterBattleText = "Let me be your\nfriend, OK?\fThen we can trade\nPOKéMON!",
  _SSAnne1FRoomsYoungsterBattleText = "I love POKéMON!\nDo you?",
  _SSAnne1FRoomsYoungsterEndBattleText = "Wow! \nYou're great!",
  _SSAnne1FSailorText = "The passengers\nare restless!\fYou might be\nchallenged by the\vmore bored ones!",
  _SSAnne1FWaiterText = "Bonjour!\nI am le waiter on\vthis ship!\fI will be happy\nto serve you any-\vthing you please!\fAh! Le strong\nsilent type!",
  _SSAnne2FRivalCutMasterText = "{RIVAL}: I heard\nthere was a CUT\vmaster on board.\fBut, he was just a\nseasick, old man!\fBut, CUT itself is\nreally useful!\fYou should go see\nhim! Smell ya!",
  _SSAnne2FRivalDefeatedText = "Humph!\fAt least you're\nraising your\vPOKéMON!",
  _SSAnne2FRivalText = "{RIVAL}: Bonjour!\n{PLAYER}!\fImagine seeing\nyou here!\f{PLAYER}, were you\nreally invited?\fSo how's your\nPOKéDEX coming?\fI already caught\n40 kinds, pal!\fDifferent kinds\nare everywhere!\fCrawl around in\ngrassy areas!",
  _SSAnne2FRivalVictoryText = "{PLAYER}! What are\nyou, seasick?\fYou should shape\nup, pal!",
  _SSAnne2FRoomsBeautyText = "I hear many people\nget seasick!",
  _SSAnne2FRoomsBrunetteGirlText = "The CAPTAIN looked\nreally sick and\vpale!",
  _SSAnne2FRoomsCooltrainerFAfterBattleText = "Oh, I adore your\nstrong POKéMON!",
  _SSAnne2FRoomsCooltrainerFBattleText = "I never saw you\nat the party.",
  _SSAnne2FRoomsCooltrainerFEndBattleText = "Take\nit easy!",
  _SSAnne2FRoomsFisherAfterBattleText = "Party?\fThe cruise ship's\nparty should be\vover by now.",
  _SSAnne2FRoomsFisherBattleText = "Check out what I\nfished up!",
  _SSAnne2FRoomsFisherEndBattleText = "I'm\nall out!",
  _SSAnne2FRoomsGentleman1AfterBattleText = "15 years ago, I\nwould have won!",
  _SSAnne2FRoomsGentleman1BattleText = "Competing against\nthe young keeps\vme youthful.",
  _SSAnne2FRoomsGentleman1EndBattleText = "Good\nfight! Ah, I feel\vyoung again!",
  _SSAnne2FRoomsGentleman2AfterBattleText = "I prefer strong\nand rare POKéMON.",
  _SSAnne2FRoomsGentleman2BattleText = "Which do you like,\na strong or a\vrare POKéMON?",
  _SSAnne2FRoomsGentleman2EndBattleText = "I must\nsalute you!",
  _SSAnne2FRoomsGentleman3Text = "In all my travels\nI've never seen\vany POKéMON sleep\vlike this one!\fIt was something\nlike this!",
  _SSAnne2FRoomsGentleman4Text = "Ah yes, I have\nseen some POKéMON\vferry people\vacross the water!",
  _SSAnne2FRoomsGentleman5Text = "Have you gone to\nthe SAFARI ZONE\vin FUCHSIA CITY?\fIt had many rare\nkinds of POKéMON!!",
  _SSAnne2FRoomsGrampsText = "POKéMON can CUT\ndown small bushes.",
  _SSAnne2FRoomsLittleBoyText = "Me and my Daddy\nthink the SAFARI\vZONE is awesome!",
  _SSAnne2FWaiterText = "This ship, she is\na luxury liner\vfor trainers!\fAt every port, we\nhold parties with\vinvited trainers!",
  _SSAnne3FSailorText = "Our CAPTAIN is a\nsword master!\fHe even teaches\nCUT to POKéMON!",
  _SSAnneB1FRoomsFisherAfterBattleText = "I was going to\nmake you my\vassistant too!",
  _SSAnneB1FRoomsFisherBattleText = "Hello stranger!\nStop and chat!\fAll my POKéMON\nare from the sea!",
  _SSAnneB1FRoomsFisherEndBattleText = "Darn!\nI let that one\vget away!",
  _SSAnneB1FRoomsMachokeText = "MACHOKE: Gwoh!\nGoggoh!",
  _SSAnneB1FRoomsSailor1AfterBattleText = "Haha! Want to be\na sailor, mate?",
  _SSAnneB1FRoomsSailor1BattleText = "You know what they\nsay about sailors\vand fighting!",
  _SSAnneB1FRoomsSailor1EndBattleText = "Right!\nGood fight, mate!",
  _SSAnneB1FRoomsSailor2AfterBattleText = "Did you see the\nFISHING GURU in\vVERMILION CITY?",
  _SSAnneB1FRoomsSailor2BattleText = "My sailor's pride\nis at stake!",
  _SSAnneB1FRoomsSailor2EndBattleText = "Your\nspirit sank me!",
  _SSAnneB1FRoomsSailor3AfterBattleText = "We caught all our\nPOKéMON while\vout at sea!",
  _SSAnneB1FRoomsSailor3BattleText = "Us sailors have\nPOKéMON too!",
  _SSAnneB1FRoomsSailor3EndBattleText = "OK, \nyou're not bad.",
  _SSAnneB1FRoomsSailor4AfterBattleText = "Sea POKéMON live\nin deep water.\vYou'll need a ROD!",
  _SSAnneB1FRoomsSailor4BattleText = "I like feisty\nkids like you!",
  _SSAnneB1FRoomsSailor4EndBattleText = "Argh!\nLost it!",
  _SSAnneB1FRoomsSailor5AfterBattleText = "Jellyfish some-\ntimes drift into\vthe ship.",
  _SSAnneB1FRoomsSailor5BattleText = "Matey, you're\nwalking the plank\vif you lose!",
  _SSAnneB1FRoomsSailor5EndBattleText = "Argh!\nBeaten by a kid!",
  _SSAnneB1FRoomsSuperNerdText = "My buddy, MACHOKE,\nis super strong!\fHe has enough\nSTRENGTH to move\vbig rocks!",
  _SSAnneBowCooltrainerMText = "Urf. I feel ill.\fI stepped out to\nget some air.",
  _SSAnneBowSailor1Text = "Scrubbing decks\nis hard work!",
  _SSAnneBowSailor2AfterBattleText = "How many kinds of\nPOKéMON do you\vthink there are?",
  _SSAnneBowSailor2BattleText = "Hey matey!\fLet's do a little\njig!",
  _SSAnneBowSailor2EndBattleText = "You're\nimpressive!",
  _SSAnneBowSailor3AfterBattleText = "My Pa said there\nare 100 kinds of\vPOKéMON. I think\vthere are more.",
  _SSAnneBowSailor3BattleText = "Ahoy there!\nAre you seasick?",
  _SSAnneBowSailor3EndBattleText = "I was\njust careless!",
  _SSAnneBowSuperNerdText = "The party's over.\nThe ship will be\vdeparting soon.",
  _SSAnneCaptainsRoomCaptainHM01NoRoomText = "Oh no! You have\nno room for this!",
  _SSAnneCaptainsRoomCaptainIFeelMuchBetterText = "CAPTAIN: Whew!\nThank you! I\vfeel much better!\fYou want to see\nmy CUT technique?\fI could show you\nif I wasn't ill...\fI know! You can\nhave this!\fTeach it to your\nPOKéMON and you\vcan see it CUT\vany time!",
  _SSAnneCaptainsRoomCaptainNotSickAnymoreText = "CAPTAIN: Whew!\fNow that I'm not\nsick any more, I\vguess it's time.",
  _SSAnneCaptainsRoomCaptainReceivedHM01Text = "{PLAYER} got\n{RAM:wStringBuffer}!",
  _SSAnneCaptainsRoomRubCaptainsBackText = "CAPTAIN: Ooargh...\nI feel hideous...\vUrrp! Seasick...\f{PLAYER} rubbed\nthe CAPTAIN's\vback!\fRub-rub...\nRub-rub...",
  _SSAnneCaptainsRoomSeasickBookText = "How to Conquer\nSeasickness...\vThe CAPTAIN's\vreading this!",
  _SSAnneCaptainsRoomTrashText = "Yuck! Shouldn't\nhave looked!",
  _SSAnneKitchenCook1Text = "You, mon petit!\nWe're busy here!\vOut of the way!",
  _SSAnneKitchenCook2Text = "I saw an odd ball\nin the trash.",
  _SSAnneKitchenCook3Text = "I'm so busy I'm\ngetting dizzy!",
  _SSAnneKitchenCook4Text = "Hum-de-hum-de-\nho...\fI peel spuds\nevery day!\vHum-hum...",
  _SSAnneKitchenCook5Text = "Did you hear about\nSNORLAX?\fAll it does is\neat and sleep!",
  _SSAnneKitchenCook6Text = "Snivel...Sniff...\fI only get to\npeel onions...\vSnivel...",
  _SSAnneKitchenCook7MainCourseIsText = "Er-hem! Indeed I\nam le CHEF!\fLe main course is",
  _SSTicketNoRoomText = "You've got too\nmuch stuff, bud!",
  _SSTicketReceivedText = "{PLAYER} received\nan {RAM:wStringBuffer}!",
  _SafariZoneAngryText = "Wild {RAM:wEnemyMonNick}\nis angry!",
  _SafariZoneCenterRestHouseGirlText = "SARA: Where did\nmy boy friend,\vERIK, go?",
  _SafariZoneCenterRestHouseScientistText = "I'm catching\nPOKéMON to take\vhome as gifts!",
  _SafariZoneCenterRestHouseSignText = "REST HOUSE",
  _SafariZoneCenterTrainerTipsSignText = "TRAINER TIPS\fPress the START\nButton to check\vremaining time!",
  _SafariZoneEastRestHouseRockerText = "I caught a\nCHANSEY!\fThat makes this\nall worthwhile!",
  _SafariZoneEastRestHouseScientistText = "How many did you\ncatch? I'm bushed\vfrom the work!",
  _SafariZoneEastRestHouseSignText = "REST HOUSE",
  _SafariZoneEastRestHouseSilphWorkerMText = "Whew! I'm tired\nfrom all the fun!",
  _SafariZoneEastSignText = "CENTER AREA\nNORTH: AREA 2",
  _SafariZoneEastTrainerTipsText = "TRAINER TIPS\fThe remaining time\ndeclines only\vwhile you walk!",
  _SafariZoneEatingText = "Wild {RAM:wEnemyMonNick}\nis eating!",
  _SafariZoneGateSafariZoneWorker1CallYouOnThePAText = "\fWe'll call you on\nthe PA when you\vrun out of time\vor SAFARI BALLs!",
  _SafariZoneGateSafariZoneWorker1GoodHaulComeAgainText = "Did you get a\ngood haul?\vCome again!",
  _SafariZoneGateSafariZoneWorker1GoodLuckText = "Good Luck!",
  _SafariZoneGateSafariZoneWorker1LeavingEarlyText = "Leaving early?",
  _SafariZoneGateSafariZoneWorker1NotEnoughMoneyText = "Oops! Not enough\nmoney!",
  _SafariZoneGateSafariZoneWorker1PleaseComeAgainText = "OK! Please come\nagain!",
  _SafariZoneGateSafariZoneWorker1ReturnSafariBallsText = "Please return any\nSAFARI BALLs you\vhave left.",
  _SafariZoneGateSafariZoneWorker1Text = "Welcome to the\nSAFARI ZONE!",
  _SafariZoneGateSafariZoneWorker1ThatllBe500PleaseText = "That'll be ¥500\nplease!\fWe only use a\nspecial POKé BALL\vhere.\f{PLAYER} received\n30 SAFARI BALLs!",
  _SafariZoneGateSafariZoneWorker1WouldYouLikeToJoinText = "For just ¥500,\nyou can catch all\vthe POKéMON you\vwant in the park!\fWould you like to\njoin the hunt?",
  _SafariZoneGateSafariZoneWorker2FirstTimeHereText = "Hi! Is it your\nfirst time here?",
  _SafariZoneGateSafariZoneWorker2SafariZoneExplanationText = "SAFARI ZONE has 4\nzones in it.\fEach zone has\ndifferent kinds\vof POKéMON. Use\vSAFARI BALLs to\vcatch them!\fWhen you run out\nof time or SAFARI\vBALLs, it's game\vover for you!\fBefore you go,\nopen an unused\vPOKéMON BOX so\vthere's room for\vnew POKéMON!",
  _SafariZoneGateSafariZoneWorker2YoureARegularHereText = "Sorry, you're a\nregular here!",
  _SafariZoneNorthRestHouseGentlemanText = "My EEVEE evolved\ninto FLAREON!\fBut, a friend's\nEEVEE turned into\va VAPOREON!\vI wonder why?",
  _SafariZoneNorthRestHouseSafariZoneWorkerText = "Go to the deepest\npart of the\vSAFARI ZONE. You\vwill win a prize!",
  _SafariZoneNorthRestHouseScientistText = "You can keep any\nitem you find on\vthe ground here.\fBut, you'll run\nout of time if\vyou try for all\vof them at once!",
  _SafariZoneNorthRestHouseSignText = "REST HOUSE",
  _SafariZoneNorthSignText = "AREA 2",
  _SafariZoneNorthTrainerTips1Text = "TRAINER TIPS\fThe SECRET HOUSE\nis still ahead!",
  _SafariZoneNorthTrainerTips2Text = "TRAINER TIPS\fPOKéMON hide in\ntall grass!\fZigzag through\ngrassy areas to\vflush them out.",
  _SafariZoneNorthTrainerTips3Text = "TRAINER TIPS\fWin a free HM for\nfinding the\vSECRET HOUSE!",
  _SafariZoneSecretHouseFishingGuruHM03ExplanationText = "HM03 is SURF!\fPOKéMON will be\nable to ferry you\vacross water!\fAnd, this HM isn't\ndisposable! You\vcan use it over\vand over!\fYou're super lucky\nfor winning this\vfabulous prize!",
  _SafariZoneSecretHouseFishingGuruHM03NoRoomText = "You don't have\nroom for this\vfabulous prize!",
  _SafariZoneSecretHouseFishingGuruReceivedHM03Text = "{PLAYER} received\n{RAM:wStringBuffer}!",
  _SafariZoneSecretHouseFishingGuruYouHaveWonText = "Ah! Finally!\fYou're the first\nperson to reach\vthe SECRET HOUSE!\fI was getting\nworried that no\vone would win our\vcampaign prize.\fCongratulations!\nYou have won!",
  _SafariZoneWestFindWardensTeethSignText = "REQUEST NOTICE\fPlease find the\nSAFARI WARDEN's\vlost GOLD TEETH.\vThey're around\vhere somewhere.\fReward offered!\nContact: WARDEN",
  _SafariZoneWestRestHouseCooltrainerMText = "Using BAIT will\nmake POKéMON\veasier to catch.",
  _SafariZoneWestRestHouseScientistText = "Tossing ROCKs at\nPOKéMON might\vmake them run,\vbut they'll be\veasier to catch.",
  _SafariZoneWestRestHouseSignText = "REST HOUSE",
  _SafariZoneWestRestHouseSilphWorkerFText = "I hiked a lot, but\nI didn't see any\vPOKéMON I wanted.",
  _SafariZoneWestSignText = "AREA 3\nEAST: CENTER AREA",
  _SafariZoneWestTrainerTipsText = "TRAINER TIPS\fZone Exploration\nCampaign!\fThe Search for\nthe SECRET HOUSE!",
  _SaffronCityFightingDojoSignText = "FIGHTING DOJO",
  _SaffronCityGentlemanText = "I flew here on my\nPIDGEOT when I\vread about SILPH.\fIt's already over?\nI missed the\vmedia action.",
  _SaffronCityGymSignText = "SAFFRON CITY\nPOKéMON GYM\vLEADER: SABRINA\fThe Master of\nPsychic POKéMON!",
  _SaffronCityMrPsychicsHouseSignText = "MR.PSYCHIC's\nHOUSE",
  _SaffronCityPidgeotText = "PIDGEOT: Bi bibii!",
  _SaffronCityPokecenterGuyText1 = "It would be great\nif the ELITE FOUR\vcame and stomped\vTEAM ROCKET!",
  _SaffronCityPokecenterGuyText2 = "TEAM ROCKET took\noff! We can go\vout safely again!\vThat's great!",
  _SaffronCityRockerText = "I saw ROCKET\nBOSS escaping\vSILPH's building.",
  _SaffronCityRocket1Text = "What do you want?\nGet lost!",
  _SaffronCityRocket2Text = "BOSS said he'll\ntake this town!",
  _SaffronCityRocket3Text = "Get out of the\nway!",
  _SaffronCityRocket4Text = "SAFFRON belongs\nto TEAM ROCKET!",
  _SaffronCityRocket5Text = "Being evil makes\nme feel so alive!",
  _SaffronCityRocket6Text = "Ow! Watch where\nyou're walking!",
  _SaffronCityRocket7Text = "With SILPH under\ncontrol, we can\vexploit POKéMON\varound the world!",
  _SaffronCityRocket8Text = "I'm a security\nguard.\fSuspicious kids I\ndon't allow in!",
  _SaffronCityRocket9Text = "...\nSnore...\fHah! He's taking\na snooze!",
  _SaffronCityScientistText = "You beat TEAM\nROCKET all alone?\vThat's amazing!",
  _SaffronCitySignText = "SAFFRON CITY\nShining, Golden\vLand of Commerce",
  _SaffronCitySilphCoLatestProductSignText = "SILPH's latest\nproduct!\fRelease to be\ndetermined...",
  _SaffronCitySilphCoSignText = "SILPH CO.\nOFFICE BUILDING",
  _SaffronCitySilphWorkerFText = "People should be\nflocking back to\vSAFFRON now.",
  _SaffronCitySilphWorkerMText = "Yeah! TEAM ROCKET\nis gone!\vIt's safe to go\vout again!",
  _SaffronCityTrainerTips1Text = "TRAINER TIPS\fFULL HEAL cures\nall ailments like\vsleep and burns.\fIt costs a bit\nmore, but it's\vmore convenient.",
  _SaffronCityTrainerTips2Text = "TRAINER TIPS\fNew GREAT BALL\noffers improved\vcapture rates.\fTry it on those\nhard-to-catch\vPOKéMON.",
  _SaffronGateGuardGeeImThirstyText = "I'm on guard duty.\nGee, I'm thirsty,\vthough!\fOh wait there,\nthe road's closed.",
  _SaffronGateGuardImParchedText = "Whoa, boy!\nI'm parched!\v...\vHuh? I can have\vthis drink?\vGee, thanks!",
  _SaffronGateGuardThanksForTheDrinkText = "Hi, thanks for\nthe cool drinks!",
  _SaffronGateGuardYouCanGoOnThroughText = "\f...\nGlug glug...\v...\vGulp...\vIf you want to go\vto SAFFRON CITY...\v...\vYou can go on\vthrough. I'll\vshare this with\vthe other guards!",
  _SaffronGymChanneler1AfterBattleText = "In a battle of\nequals, the one\vwith the stronger\vwill wins!\fIf you wish\nto beat SABRINA,\vfocus on winning!",
  _SaffronGymChanneler1BattleText = "SABRINA is younger\nthan I, but I\vrespect her!",
  _SaffronGymChanneler1EndBattleText = "Not\ngood enough!",
  _SaffronGymChanneler2AfterBattleText = "I must teach\nbetter techniques\vto my POKéMON!",
  _SaffronGymChanneler2BattleText = "POKéMON take on\nthe appearance of\vtheir trainers.\fYour POKéMON must\nbe tough, then!",
  _SaffronGymChanneler2EndBattleText = "I knew\nit!",
  _SaffronGymChanneler3AfterBattleText = "I knew that this\nwas going to take\vplace.",
  _SaffronGymChanneler3BattleText = "You and I, our\nPOKéMON shall\vfight!",
  _SaffronGymChanneler3EndBattleText = "I lost\nafter all!",
  _SaffronGymGuideBeatSabrinaText = "Psychic power,\nhuh?\fIf I had that,\nI'd make a bundle\vat the slots!",
  _SaffronGymGuideChampInMakingText = "Yo! Champ in\nmaking!\fSABRINA's POKéMON\nuse psychic power\vinstead of force!\fFighting POKéMON\nare weak against\vpsychic POKéMON!\fThey get creamed\nbefore they can\veven aim a punch!",
  _SaffronGymSabrinaMarshBadgeInfoText = "The MARSHBADGE\nmakes POKéMON up\vto L70 obey you!\fStronger POKéMON\nwill become wild,\vignoring your\vorders in battle!\fJust don't raise\nyour POKéMON too\vmuch!\fWait, please take\nthis TM with you!",
  _SaffronGymSabrinaPostBattleAdviceText = "Everyone has\npsychic power!\vPeople just don't\vrealize it!",
  _SaffronGymSabrinaReceivedMarshBadgeText = "I'm\nshocked!\vBut, a loss is a\vloss.\fI admit I didn't\nwork hard enough\vto win!\fYou earned the\nMARSHBADGE!",
  _SaffronGymSabrinaReceivedTM46Text = "{PLAYER} received\nTM46!",
  _SaffronGymSabrinaTM46NoRoomText = "Your pack is full\nof other items!",
  _SaffronGymSabrinaText = "I had a vision of\nyour arrival!\fI have had psychic\npowers since I\vwas a child.\fI first learned\nto bend spoons\vwith my mind.\fI dislike fight-\ning, but if you\vwish, I will show\vyou my powers!",
  _SaffronGymYoungster1AfterBattleText = "Psychic POKéMON\nfear only ghosts\vand bugs!",
  _SaffronGymYoungster1BattleText = "Does our unseen\npower scare you?",
  _SaffronGymYoungster1EndBattleText = "I never\nforesaw this!",
  _SaffronGymYoungster2AfterBattleText = "SABRINA just wiped\nout the KARATE\vMASTER next door!",
  _SaffronGymYoungster2BattleText = "You know that\npower alone isn't\venough!",
  _SaffronGymYoungster2EndBattleText = "I don't\nbelieve this!",
  _SaffronGymYoungster3AfterBattleText = "There used to be\n2 POKéMON GYMs in\vSAFFRON.\fThe FIGHTING DOJO\nnext door lost\vits GYM status\vwhen we went and\vcreamed them!",
  _SaffronGymYoungster3BattleText = "SABRINA is young,\nbut she's also\vour LEADER!\fYou won't reach\nher easily!",
  _SaffronGymYoungster3EndBattleText = "I lost\nmy concentration!",
  _SaffronGymYoungster4AfterBattleText = "That's right! I\nused telepathy to\vread your mind!",
  _SaffronGymYoungster4BattleText = "SAFFRON POKéMON\nGYM is famous for\vits psychics!\fYou want to see\nSABRINA!\vI can tell!",
  _SaffronGymYoungster4EndBattleText = "Arrrgh!",
  _SaffronMartCooltrainerFText = "REVIVE is costly,\nbut it revives\vfainted POKéMON!",
  _SaffronMartSuperNerdText = "MAX REPEL lasts\nlonger than SUPER\vREPEL for keeping\vweaker POKéMON\vaway!",
  _SaffronPidgeyHouseBrunetteGirlText = "Thank you for\nwriting. I hope\vto see you soon!\fHey! Don't look\nat my letter!",
  _SaffronPidgeyHousePaperText = "I was given a PP\nUP as a gift.\fIt's used for\nincreasing the PP\vof techniques!",
  _SaffronPidgeyHousePidgeyText = "PIDGEY: Kurukkoo!",
  _SaffronPidgeyHouseYoungsterText = "The COPYCAT is\ncute! I'm getting\vher a POKé DOLL!",
  _SaffronPokecenterBeautyText = "POKéMON growth\nrates differ from\vspecie to specie.",
  _SaffronPokecenterGentlemanText = "SILPH CO. is very\nfamous. That's\vwhy it attracted\vTEAM ROCKET!",
  _SandshrewDexEntry = "Burrows deep\nunderground in\narid locations\ffar from water.\nIt only emerges\nto hunt for food",
  _SandslashDexEntry = "Curls up into a\nspiny ball when\nthreatened. It\fcan roll while\ncurled up to\nattack or escape",
  _SaveOptionText = "The SAVE option is\non the MENU\vscreen.",
  _SavingEnergyText = "{USER}\nis saving energy!",
  _ScaredText = "{RAM:wBattleMonNick} is too\nscared to move!",
  _ScytherDexEntry = "With ninja-like\nagility and speed,\nit can create the\fillusion that\nthere is more\nthan one",
  _SeadraDexEntry = "Capable of swim-\nming backwards by\nrapidly flapping\fits wing-like\npectoral fins and\nstout tail",
  _SeafoamIslandsB4FArticunoBattleText = "Gyaoo!",
  _SeafoamIslandsB4FBouldersSignText = "Boulders might\nchange the flow\vof water!",
  _SeafoamIslandsB4FDangerSignText = "DANGER\nFast current!",
  _SeakingDexEntry = "In the autumn\nspawning season,\nthey can be seen\fswimming power-\nfully up rivers\nand creeks",
  _SeelDexEntry = "The protruding\nhorn on its head\nis very hard.\fIt is used for\nbashing through\nthick ice",
  _SentToBoxText = "There's no more\nroom for POKéMON!\v{RAM:wBoxMonNicks} was\vsent to POKéMON\vBOX {RAM:wStringBuffer} on PC!",
  _ShallWeHealYourPokemonText = "Shall we heal your\nPOKéMON?",
  _ShellderDexEntry = "Its hard shell\nrepels any kind\nof attack.\fIt is vulnerable\nonly when its\nshell is open",
  _ShroudedInMistText = "{USER}'s\nshrouded in mist!",
  _SilphCo10FGiovanniILostAgainText = "Arrgh!!\nI lost again!?",
  _SilphCo10FPorygonText = "The monitor has\nPOKéMON on it!",
  _SilphCo10FRocketAfterBattleText = "Nice try, but the\nboardroom is up\vone more floor!",
  _SilphCo10FRocketBattleText = "Welcome to the\n10F! So good of\vyou to join me!",
  _SilphCo10FRocketEndBattleText = "I'm\nstunned!",
  _SilphCo10FScientistAfterBattleText = "Are you satisfied\nwith beating me?\vThen go on home!",
  _SilphCo10FScientistBattleText = "Enough of your\nsilly games!",
  _SilphCo10FScientistEndBattleText = "No\ncontinues left!",
  _SilphCo10FSilphWorkerFImScaredText = "Waaaaa!\vI'm scared!",
  _SilphCo10FSilphWorkerFQuietAboutMyCryingText = "Please keep quiet\nabout my crying!",
  _SilphCo11FBeautyText = "SECRETARY: Thank\nyou for rescuing\vall of us!\fWe admire your\ncourage.",
  _SilphCo11FGiovanniText = "Ah {PLAYER}!\nSo we meet again!\fThe PRESIDENT and\nI are discussing\va vital business\vproposition.\fKeep your nose\nout of grown-up\vmatters...\fOr, experience a\nworld of pain!",
  _SilphCo11FGiovanniYouRuinedOurPlansText = "Blast it all!\nYou ruined our\vplans for SILPH!\fBut, TEAM ROCKET\nwill never fall!\f{PLAYER}! Never\nforget that all\vPOKéMON exist\vfor TEAM ROCKET!\fI must go, but I\nshall return!",
  _SilphCo11FRocket1AfterBattleText = "So, you want to\nsee my BOSS?",
  _SilphCo11FRocket1BattleText = "Stop right there!\nDon't you move!",
  _SilphCo11FRocket1EndBattleText = "Don't...\nPlease!",
  _SilphCo11FRocket2AfterBattleText = "Watch your step,\nmy BOSS likes his\vPOKéMON tough!",
  _SilphCo11FRocket2BattleText = "Halt! Do you have\nan appointment\vwith my BOSS?",
  _SilphCo11FRocket2EndBattleText = "Gaah!\nDemolished!",
  _SilphCo11FSilphPresidentMasterBallDescriptionText = "PRESIDENT: You\ncan't buy that\vanywhere!\fIt's our secret\nprototype MASTER\vBALL!\fIt will catch any\nPOKéMON without\vfail!\fYou should be\nquiet about using\vit, though.",
  _SilphCo11FSilphPresidentNoRoomText = "You have no\nroom for this.",
  _SilphCo11FSilphPresidentReceivedMasterBallText = "{PLAYER} got a\n{RAM:wStringBuffer}!",
  _SilphCo11FSilphPresidentText = "PRESIDENT: Thank\nyou for saving\vSILPH!\fI will never\nforget you saved\vus in our moment\vof peril!\fI have to thank\nyou in some way!\fBecause I am rich,\nI can give you\vanything!\fHere, maybe this\nwill do!",
  _SilphCo1FLinkReceptionistText = "Welcome!\fThe PRESIDENT is\nin the boardroom\von 11F!",
  _SilphCo2FRocket1AfterBattleText = "Diamond shaped\ntiles are\vteleport blocks!\fThey're hi-tech\ntransporters!",
  _SilphCo2FRocket1BattleText = "No kids are\nallowed in here!",
  _SilphCo2FRocket1EndBattleText = "Tough!",
  _SilphCo2FRocket2AfterBattleText = "SILPH CO. will\nbe merged with\vTEAM ROCKET!",
  _SilphCo2FRocket2BattleText = "Hey kid! What are\nyou doing here?",
  _SilphCo2FRocket2EndBattleText = "I goofed!",
  _SilphCo2FScientist1AfterBattleText = "I work for both\nSILPH and TEAM\vROCKET!",
  _SilphCo2FScientist1BattleText = "Help! I'm a SILPH\nemployee.",
  _SilphCo2FScientist1EndBattleText = "How\ndid you know I\vwas a ROCKET?",
  _SilphCo2FScientist2AfterBattleText = "Can you solve the\nmaze in here?",
  _SilphCo2FScientist2BattleText = "It's off limits\nhere! Go home!",
  _SilphCo2FScientist2EndBattleText = "You're\ngood.",
  _SilphCo2FSilphWorkerFReceivedTM36Text = "{PLAYER} got\n{RAM:wStringBuffer}!",
  _SilphCo2FSilphWorkerFTM36ExplanationText = "TM36 is\nSELFDESTRUCT!\fIt's powerful, but\nthe POKéMON that\vuses it faints!\vBe careful.",
  _SilphCo2FSilphWorkerFTM36NoRoomText = "You don't have any\nroom for this.",
  _SilphCo3FRocketAfterBattleText = "A hint? You can\nopen doors with a\vCARD KEY!",
  _SilphCo3FRocketBattleText = "Quit messing with\nus, kid!",
  _SilphCo3FRocketEndBattleText = "I give\nup!",
  _SilphCo3FScientistAfterBattleText = "Humph...\fTEAM ROCKET said\nthat if I helped\vthem, they'd let\vme study POKéMON!",
  _SilphCo3FScientistBattleText = "I support TEAM\nROCKET more than\vI support SILPH!",
  _SilphCo3FScientistEndBattleText = "You\nreally got me!",
  _SilphCo3FSilphWorkerMWhatShouldIDoText = "I work for SILPH.\nWhat should I do?",
  _SilphCo3FSilphWorkerMYouSavedUsText = "{PLAYER}! You and\nyour POKéMON\vsaved us!",
  _SilphCo4FRocket1AfterBattleText = "Fwahahaha!\nMy BOSS has been\vafter this place!",
  _SilphCo4FRocket1BattleText = "TEAM ROCKET has\ntaken command of\vSILPH CO.!",
  _SilphCo4FRocket1EndBattleText = "Arrgh!",
  _SilphCo4FRocket2AfterBattleText = "I better tell the\nBOSS on 11F!",
  _SilphCo4FRocket2BattleText = "Intruder spotted!",
  _SilphCo4FRocket2EndBattleText = "Who\nare you?",
  _SilphCo4FScientistAfterBattleText = "The doors are\nelectronically\vlocked! A CARD\vKEY opens them!",
  _SilphCo4FScientistBattleText = "My POKéMON are my\nloyal soldiers!",
  _SilphCo4FScientistEndBattleText = "Darn!\nYou weak POKéMON!",
  _SilphCo4FSilphWorkerMImHidingText = "Sssh! Can't you\nsee I'm hiding?",
  _SilphCo4FSilphWorkerMTeamRocketIsGoneText = "Huh? TEAM ROCKET\nis gone?",
  _SilphCo5FPokemonReport1Text = "It's a POKéMON\nREPORT!\fPOKéMON LAB\ncreated PORYGON,\vthe first virtual\vreality POKéMON.",
  _SilphCo5FPokemonReport2Text = "It's a POKéMON\nREPORT!\fOver 160 POKéMON\ntechniques have\vbeen confirmed.",
  _SilphCo5FPokemonReport3Text = "It's a POKéMON\nREPORT!\f4 POKéMON evolve\nonly when traded\vby link-cable.",
  _SilphCo5FRockerAfterBattleText = "You're only on 5F.\nIt's a long way\vto my BOSS!",
  _SilphCo5FRockerBattleText = "Whaaat? There\nshouldn't be any\vchildren here?",
  _SilphCo5FRockerEndBattleText = "Oh\ngoodness!",
  _SilphCo5FRocket1AfterBattleText = "It's not smart\nto pick a fight\vwith TEAM ROCKET!",
  _SilphCo5FRocket1BattleText = "I heard a kid was\nwandering around.",
  _SilphCo5FRocket1EndBattleText = "Boom!",
  _SilphCo5FRocket2AfterBattleText = "Which reminds me.\fKOFFING evolves\ninto WEEZING!",
  _SilphCo5FRocket2BattleText = "Show TEAM ROCKET\na little respect!",
  _SilphCo5FRocket2EndBattleText = "Cough...\nCough...",
  _SilphCo5FScientistAfterBattleText = "We worked on the\nultimate POKé\vBALL which would\vcatch anything!",
  _SilphCo5FScientistBattleText = "We study POKé\nBALL technology\von this floor!",
  _SilphCo5FScientistEndBattleText = "Dang!\nBlast it!",
  _SilphCo5FSilphWorkerMThatsYouRightText = "TEAM ROCKET is\nin an uproar over\vsome intruder.\vThat's you right?",
  _SilphCo5FSilphWorkerMYoureOurHeroText = "TEAM ROCKET took\noff! You're our\vhero! Thank you!",
  _SilphCo6FRocket1AfterBattleText = "No matter!\nMy brothers will\vavenge me!",
  _SilphCo6FRocket1BattleText = "I am one of the 4\nROCKET BROTHERS!",
  _SilphCo6FRocket1EndBattleText = "Flame\nout!",
  _SilphCo6FRocket2AfterBattleText = "If you stand for\njustice, you\vbetray evil!",
  _SilphCo6FRocket2BattleText = "You dare betray\nTEAM ROCKET?",
  _SilphCo6FRocket2EndBattleText = "You\ntraitor!",
  _SilphCo6FScientistAfterBattleText = "TIKSI BRANCH?\nIt's in Russian\vno man's land!",
  _SilphCo6FScientistBattleText = "That rotten\nPRESIDENT!\fHe shouldn't have\nsent me to the\vTIKSI BRANCH!",
  _SilphCo6FScientistEndBattleText = "Shoot!",
  _SilphCo6FSilphWorkerF1HaveToMarryHimText = "I feel so sorry\nfor him, I have\vto marry him!",
  _SilphCo6FSilphWorkerF1SuchACowardText = "Look at him! He's\nsuch a coward!",
  _SilphCo6FSilphWorkerF2TeamRocketConquerWorldText = "TEAM ROCKET is\ntrying to conquer\vthe world with\vPOKéMON!",
  _SilphCo6FSilphWorkerF2TeamRocketRanText = "TEAM ROCKET ran\nbecause of you!",
  _SilphCo6FSilphWorkerM1BackToWorkText = "Well, better get\nback to work!",
  _SilphCo6FSilphWorkerM1TookOverTheBuildingText = "The ROCKETs came\nand took over the\vbuilding!",
  _SilphCo6FSilphWorkerM3TargetedSilphText = "They must have\ntargeted SILPH\vfor our POKéMON\vproducts.",
  _SilphCo6FSilphWorkerM3WorkForSilphText = "Come work for\nSILPH when you\vget older!",
  _SilphCo6FSilphWorkerMHelpMePleaseText = "Oh dear, oh dear.\nHelp me please!",
  _SilphCo6FSilphWorkerMWeGotEngagedText = "We got engaged!\nHeheh!",
  _SilphCo7FRivalDefeatedText = "Oh ho!\nSo, you are ready\vfor BOSS ROCKET!",
  _SilphCo7FRivalGoodLuckToYouText = "Well, {PLAYER}!\fI'm moving on up\nand ahead!\fBy checking my\nPOKéDEX, I'm\vstarting to see\vwhat's strong and\vhow they evolve!\fI'm going to the\nPOKéMON LEAGUE\vto boot out the\vELITE FOUR!\fI'll become the\nworld's most\vpowerful trainer!\f{PLAYER}, well\ngood luck to you!\vDon't sweat it!\vSmell ya!",
  _SilphCo7FRivalText = "{RIVAL}: What\nkept you {PLAYER}?",
  _SilphCo7FRivalVictoryText = "{RIVAL}: How can\nI put this?\fYou're not good\nenough to play\vwith us big boys!",
  _SilphCo7FRivalWaitedHereText = "{RIVAL}: Hahaha!\nI thought you'd\vturn up if I\vwaited here!\fI guess TEAM\nROCKET slowed you\vdown! Not that I\vcare!\fI saw you in\nSAFFRON, so I\vdecided to see if\vyou got better!",
  _SilphCo7FRocket1AfterBattleText = "You won't find my\nBOSS by just\vscurrying around!",
  _SilphCo7FRocket1BattleText = "Oh ho! I smell a\nlittle rat!",
  _SilphCo7FRocket1EndBattleText = "Lights\nout!",
  _SilphCo7FRocket2AfterBattleText = "Doesn't matter.\nMy brothers will\vrepay the favor!",
  _SilphCo7FRocket2BattleText = "I am one of the 4\nROCKET BROTHERS!",
  _SilphCo7FRocket2EndBattleText = "Aack!\nBrothers, I lost!",
  _SilphCo7FRocket3AfterBattleText = "Go on home\nbefore my BOSS\vgets ticked off!",
  _SilphCo7FRocket3BattleText = "A child intruder?\nThat must be you!",
  _SilphCo7FRocket3EndBattleText = "Fine!\nI lost!",
  _SilphCo7FScientistAfterBattleText = "Despite your age,\nyou are a skilled\vtrainer!",
  _SilphCo7FScientistBattleText = "Heheh!\fYou mistook me for\na SILPH worker?",
  _SilphCo7FScientistEndBattleText = "I'm\ndone!",
  _SilphCo7FSilphWorkerM1HaveThisPokemonText = "Oh! Hi! You're\nnot a ROCKET! You\vcame to save us?\vWhy, thank you!\fI want you to\nhave this POKéMON\vfor saving us.",
  _SilphCo7FSilphWorkerM1IsOurPresidentOkText = "TEAM ROCKET's\nBOSS went to the\vboardroom! Is our\vPRESIDENT OK?",
  _SilphCo7FSilphWorkerM1LaprasDescriptionText = "It's LAPRAS. It's\nvery intelligent.\fWe kept it in our\nlab, but it will\vbe much better\voff with you!\fI think you will\nbe a good trainer\vfor LAPRAS!\fIt's a good\nswimmer. It'll\vgive you a lift!",
  _SilphCo7FSilphWorkerM1SavedText = "Saved at last!\nThank you!",
  _SilphCo7FSilphWorkerM2AfterTheMasterBallText = "TEAM ROCKET was\nafter the MASTER\vBALL which will\vcatch any POKéMON!",
  _SilphCo7FSilphWorkerM2CancelledMasterBallText = "We canceled the\nMASTER BALL\vproject because\vof TEAM ROCKET.",
  _SilphCo7FSilphWorkerM3ItWouldBeBadText = "It would be bad\nif TEAM ROCKET\vtook over SILPH\vor our POKéMON!",
  _SilphCo7FSilphWorkerM3YouChasedOffTeamRocketText = "Wow! You chased\noff TEAM ROCKET\vall by yourself?",
  _SilphCo7FSilphWorkerM4ItsReallyDangerousHereText = "You! It's really\ndangerous here!\vYou came to save\vme? You can't!",
  _SilphCo7FSilphWorkerM4SafeAtLastText = "Safe at last!\nOh thank you!",
  _SilphCo8FRocket1AfterBattleText = "If you don't turn\nback, I'll call\vfor backup!",
  _SilphCo8FRocket1BattleText = "That's as far as\nyou'll go!",
  _SilphCo8FRocket1EndBattleText = "Not\nenough grit!",
  _SilphCo8FRocket2AfterBattleText = "I'll leave you up\nto my brothers!",
  _SilphCo8FRocket2BattleText = "I am one of the 4\nROCKET BROTHERS!",
  _SilphCo8FRocket2EndBattleText = "Whoo!\nOh brothers!",
  _SilphCo8FScientistAfterBattleText = "So, what do you\nthink of SILPH\vBUILDING's maze?",
  _SilphCo8FScientistBattleText = "You're causing us\nproblems!",
  _SilphCo8FScientistEndBattleText = "Huh?\nI lost?",
  _SilphCo8FSilphWorkerMSilphIsFinishedText = "I wonder if SILPH\nis finished...",
  _SilphCo8FSilphWorkerMThanksForSavingUsText = "Thanks for saving\nus!",
  _SilphCo9FRocket1AfterBattleText = "If I had started\nas a trainer at\vyour age...",
  _SilphCo9FRocket1BattleText = "Your POKéMON seem\nto adore you, kid!",
  _SilphCo9FRocket1EndBattleText = "Ghaaah!",
  _SilphCo9FRocket2AfterBattleText = "My brothers will\navenge me!",
  _SilphCo9FRocket2BattleText = "I am one of the 4\nROCKET BROTHERS!",
  _SilphCo9FRocket2EndBattleText = "Warg!\nBrothers, I lost!",
  _SilphCo9FScientistAfterBattleText = "Exploiting weak\nspots does work!\vThink about\velement types!",
  _SilphCo9FScientistBattleText = "Your POKéMON have\nweak points! I\vcan nail them!",
  _SilphCo9FScientistEndBattleText = "You\nhammered me!",
  _SkyAttackGlowingText = "\nis glowing!",
  _SlowbroDexEntry = "The SHELLDER that\nis latched onto\nSLOWPOKE's tail\fis said to feed\non the host's left\nover scraps",
  _SlowpokeDexEntry = "Incredibly slow\nand dopey. It\ntakes 5 seconds\ffor it to feel\npain when under\nattack",
