  _SorryNeedMoreCoinsText = "Sorry, you need\nmore coins.",
  _SpearowDexEntry = "Eats bugs in\ngrassy areas. It\nhas to flap its\fshort wings at\nhigh speed to\nstay airborne",
  _SquirtleDexEntry = "After birth, its\nback swells and\nhardens into a\fshell. Powerfully\nsprays foam from\nits mouth",
