  _TryingToLearnText = "{RAM:wLearnMoveMonName} is\ntrying to learn\v{RAM:wStringBuffer}!\fBut, {RAM:wLearnMoveMonName}\ncan't learn more\vthan 4 moves!\fDelete an older\nmove to make room\vfor {RAM:wStringBuffer}?",
  _TurnPageText = "Turn the page?",
  _TurnedAwayText = "{RAM:wBattleMonNick} turned\naway!",
  _TurnedOnPC1Text = "{PLAYER} turned on\nthe PC.",
  _TurnedOnPC2Text = "{PLAYER} turned on\nthe PC.",
  _UnaffectedText = "{TARGET}'s\nunaffected!",
  _UndergroundPathRoute6GirlText = "People often lose\nthings in that\vUNDERGROUND PATH.",
  _UndergroundPathRoute7CopyUnusedGirlText = "I want to shop at\nthe dept. store\vin CELADON but...\fThere are so many\nrough looking\vpeople there.",
  _UndergroundPathRoute7CopyUnusedGoesUnderSaffronText = "The UNDERGROUND\nPATH goes beneath\vSAFFRON and leads\vto LAVENDER.\fIf you're heading\nto CERULEAN, go\vto the building\vacross the road.",
  _UndergroundPathRoute7CopyUnusedMiddleAgedManText = "You're here to\nshop in CELADON?\fJust step outside\nand head west!",
  _UndergroundPathRoute7CopyUnusedTeamRocketHadAHideoutText = "TEAM ROCKET had a\nsecret hideout in\vCELADON CITY?",
  _UndergroundPathRoute7MiddleAgedManText = "I heard a sleepy\nPOKéMON appeared\vnear CELADON CITY.",
  _UndergroundPathRoute8GirlText = "The dept. store\nin CELADON has a\vgreat selection!",
  _UnleashedEnergyText = "{USER}\nunleashed energy!",
  _UnusedBenchGuyText1 = "I wish I could\ncatch POKéMON.",
  _UnusedBenchGuyText2 = "I'm tired from\nall the fun...",
  _UnusedBenchGuyText3 = "SILPH's manager\nis hiding in the\vSAFARI ZONE.",
  _UnveiledGhostText = "SILPH SCOPE\nunveiled the\vGHOST's identity!",
  _UseNextMonText = "Use next POKéMON?",
  _UsedCutText = "{RAM:wNameBuffer} hacked\naway with CUT!",
  _UsedInsteadText = "instead,\v",
  _UsedMove1Text = "\nused ",
  _UsedMove2Text = "\nused ",
  _UsedStrengthText = "{RAM:wNameBuffer} used\nSTRENGTH.",
  _VaporeonDexEntry = "Lives close to\nwater. Its long\ntail is ridged\fwith a fin which\nis often mistaken\nfor a mermaid's",
  _VendingMachineText1 = "A vending machine!\nHere's the menu!",
  _VendingMachineText4 = "Oops, not enough\nmoney!",
  _VendingMachineText5 = "{RAM:wStringBuffer}\npopped out!",
  _VendingMachineText6 = "There's no more\nroom for stuff!",
  _VendingMachineText7 = "Not thirsty!",
  _VenomothDexEntry = "The dust-like\nscales covering\nits wings are\fcolor coded to\nindicate the kinds\nof poison it has",
  _VenonatDexEntry = "Lives in the\nshadows of tall\ntrees where it\feats insects. It\nis attracted by\nlight at night",
  _VenusaurDexEntry = "The plant blooms\nwhen it is\nabsorbing solar\fenergy. It stays\non the move to\nseek sunlight",
  _VermilionCityBeautyText = "We're careful\nabout pollution!\fWe've heard GRIMER\nmultiplies in\vtoxic sludge!",
  _VermilionCityGambler1DidYouSeeText = "Did you see S.S.\nANNE moored in\vthe harbor?",
  _VermilionCityGambler1SSAnneDepartedText = "So, S.S.ANNE has\ndeparted!\fShe'll be back in\nabout a year.",
  _VermilionCityGambler2Text = "I'm putting up a\nbuilding on this\vplot of land.\fMy POKéMON is\ntamping the land.",
  _VermilionCityGymSignText = "VERMILION CITY\nPOKéMON GYM\vLEADER: LT.SURGE\fThe Lightning \nAmerican!",
  _VermilionCityHarborSignText = "VERMILION HARBOR",
  _VermilionCityMachopStompingTheLandFlatText = "\fA MACHOP is\nstomping the land\vflat.",
  _VermilionCityMachopText = "MACHOP: Guoh!\nGogogoh!",
  _VermilionCityNoticeSignText = "NOTICE!\fROUTE 12 may be\nblocked off by a\vsleeping POKéMON.\fDetour through\nROCK TUNNEL to\vLAVENDER TOWN.\fVERMILION POLICE",
  _VermilionCityPokemonFanClubSignText = "POKéMON FAN CLUB\nAll POKéMON fans\vwelcome!",
  _VermilionCitySailor1DoYouHaveATicketText = "Welcome to S.S.\nANNE!\fExcuse me, do you\nhave a ticket?",
  _VermilionCitySailor1FlashedTicketText = "{PLAYER} flashed\nthe S.S.TICKET!\fGreat! Welcome to\nS.S.ANNE!",
  _VermilionCitySailor1ShipSetSailText = "The ship set sail.",
  _VermilionCitySailor1WelcomeToSSAnneText = "Welcome to S.S.\nANNE!",
  _VermilionCitySailor1YouNeedATicketText = "{PLAYER} doesn't\nhave the needed\vS.S.TICKET.\fSorry!\fYou need a ticket\nto get aboard.",
  _VermilionCitySailor2Text = "S.S.ANNE is a\nfamous luxury\vcruise ship.\fWe visit VERMILION\nonce a year.",
  _VermilionCitySignText = "VERMILION CITY\nThe Port of\vExquisite Sunsets",
  _VermilionDockUnusedText = "",
  _VermilionGymGentlemanAfterBattleText = "The door won't\nopen?\fLT.SURGE always\nwas cautious!",
  _VermilionGymGentlemanBattleText = "When I was in the\nArmy, LT.SURGE\vwas my strict CO!",
  _VermilionGymGentlemanEndBattleText = "Stop!\nYou're very good!",
  _VermilionGymGymGuideBeatLTSurgeText = "Whew! That match\nwas electric!",
  _VermilionGymGymGuideChampInMakingText = "Yo! Champ in\nmaking!\fLT.SURGE has a\nnickname. People\vrefer to him as\vthe Lightning\vAmerican!\fHe's an expert on\nelectric POKéMON!\fBirds and water\nPOKéMON are at\vrisk! Beware of\vparalysis too!\fLT.SURGE is very\ncautious!\fYou'll have to\nbreak a code to\vget to him!",
  _VermilionGymLTSurgePostBattleAdviceText = "A little word of\nadvice, kid!\fElectricity is\nsure powerful!\fBut, it's useless\nagainst ground-\vtype POKéMON!",
  _VermilionGymLTSurgePreBattleText = "Hey, kid! What do\nyou think you're\vdoing here?\fYou won't live\nlong in combat!\vThat's for sure!\fI tell you kid,\nelectric POKéMON\vsaved me during\vthe war!\fThey zapped my\nenemies into\vparalysis!\fThe same as I'll\ndo to you!",
  _VermilionGymLTSurgeReceivedTM24Text = "{PLAYER} received \n{RAM:wStringBuffer}!",
  _VermilionGymLTSurgeReceivedThunderBadgeText = "Whoa!\fYou're the real\ndeal, kid!\fFine then, take\nthe THUNDERBADGE!",
  _VermilionGymLTSurgeTM24NoRoomText = "Yo kid, make room\nin your pack!",
  _VermilionGymLTSurgeThunderBadgeInfoText = "The THUNDERBADGE\ncranks up your\vPOKéMON's SPEED!\fIt also lets your\nPOKéMON FLY any\vtime, kid!\fYou're special,\nkid! Take this!",
  _VermilionGymSailorAfterBattleText = "LT.SURGE set up\ndouble locks!\vHere's a hint!\fWhen you open the\n1st lock, the 2nd\vlock is right\vnext to it!",
  _VermilionGymSailorBattleText = "This is no place\nfor kids!",
  _VermilionGymSailorEndBattleText = "Wow!\nSurprised me!",
  _VermilionGymSuperNerdAfterBattleText = "OK, I'll talk!\fLT.SURGE said he\nhid door switches\vinside something!",
  _VermilionGymSuperNerdBattleText = "I'm a lightweight,\nbut I'm good with\velectricity!",
  _VermilionGymSuperNerdEndBattleText = "Fried!",
  _VermilionGymTrashFailText = "Nope! There's\nonly trash here.\vHey! The electric\vlocks were reset!",
  _VermilionGymTrashSuccessText1 = "Hey! There's a\nswitch under the\vtrash!\vTurn it on!\fThe 1st electric\nlock opened!",
  _VermilionGymTrashSuccessText2 = "Hey! There's\nanother switch\vunder the trash!\vTurn it on!",
  _VermilionGymTrashSuccessText3 = "The 2nd electric\nlock opened!\fThe motorized door\nopened!",
  _VermilionGymTrashText = "Nope, there's\nonly trash here.",
  _VermilionMartCooltrainerFText = "I think POKéMON\ncan be good or\vevil. It depends\von the trainer.",
  _VermilionMartCooltrainerMText = "There are evil\npeople who will\vuse POKéMON for\vcriminal acts.\fTEAM ROCKET\ntraffics in rare\vPOKéMON.\fThey also abandon\nPOKéMON that they\vconsider not to\vbe popular or\vuseful.",
  _VermilionOldRodHouseFishingGuruDoYouLikeToFishText = "I'm the FISHING\nGURU!\fI simply Looove\nfishing!\fDo you like to\nfish?",
  _VermilionOldRodHouseFishingGuruFishingIsAWayOfLifeText = "\fFishing is a way\nof life!\fFrom the seas to\nrivers, go out\vand land the big\vone, young one!",
  _VermilionOldRodHouseFishingGuruHowAreTheFishBitingText = "Hello there,\n{PLAYER}!\fHow are the fish\nbiting?",
  _VermilionOldRodHouseFishingGuruNoRoomText = "Oh no!\fYou have no room\nfor my gift!",
  _VermilionOldRodHouseFishingGuruTakeThisText = "Grand! I like\nyour style!\fTake this and\nfish, young one!\f{PLAYER} received\nan {RAM:wStringBuffer}!",
  _VermilionOldRodHouseFishingGuruThatsSoDisappointingText = "Oh... That's so\ndisappointing...",
  _VermilionPidgeyHouseLetterText = "Dear PIPPI, I hope\nto see you soon.\fI heard SAFFRON\nhas problems with\vTEAM ROCKET.\fVERMILION appears\nto be safe.",
  _VermilionPidgeyHousePidgeyText = "PIDGEY: Kurukkoo!",
  _VermilionPidgeyHouseYoungsterText = "I'm getting my\nPIDGEY to fly a\vletter to SAFFRON\vin the north!",
  _VermilionPokecenterFishingGuruText = "Even if they are\nthe same level,\vPOKéMON can have\vvery different\vabilities.\fA POKéMON raised\nby a trainer is\vstronger than one\vin the wild.",
  _VermilionPokecenterGuyText = "It is true that a\nhigher level\vPOKéMON will be\vmore powerful...\fBut, all POKéMON\nwill have weak\vpoints against\vspecific types.\fSo, there is no\nuniversally\vstrong POKéMON.",
  _VermilionPokecenterSailorText = "My POKéMON was\npoisoned! It\vfainted while we\vwere walking!",
  _VictoryRoad1FCooltrainerFAfterBattleText = "I never wanted to\nlose to anybody!",
  _VictoryRoad1FCooltrainerFBattleText = "I wonder if you\nare good enough\vfor me!",
  _VictoryRoad1FCooltrainerFEndBattleText = "I\nlost out!",
  _VictoryRoad1FCooltrainerMAfterBattleText = "I concede, you're\nbetter than me!",
  _VictoryRoad1FCooltrainerMBattleText = "I can see you're\ngood! Let me see\vexactly how good!",
  _VictoryRoad1FCooltrainerMEndBattleText = "I\nhad a chance...",
  _VictoryRoad2FCooltrainerMAfterBattleText = "You earned the\nright to be on\vVICTORY ROAD!",
  _VictoryRoad2FCooltrainerMBattleText = "Come on!\nI'll whip you!",
  _VictoryRoad2FCooltrainerMEndBattleText = "I got\nwhipped!",
  _VictoryRoad2FHikerAfterBattleText = "If you get stuck,\ntry moving some\vboulders around!",
  _VictoryRoad2FHikerBattleText = "VICTORY ROAD is\nthe final test\vfor trainers!",
  _VictoryRoad2FHikerEndBattleText = "Aiyah!",
  _VictoryRoad2FMoltresBattleText = "Gyaoo!",
  _VictoryRoad2FSuperNerd1AfterBattleText = "{RIVAL} also came\nthrough here!",
  _VictoryRoad2FSuperNerd1BattleText = "Ah, so you wish\nto challenge the\vELITE FOUR?",
  _VictoryRoad2FSuperNerd1EndBattleText = "You\ngot me!",
  _VictoryRoad2FSuperNerd2AfterBattleText = "I can beat you\nwhen it comes to\vknowledge about\vPOKéMON!",
  _VictoryRoad2FSuperNerd2BattleText = "If you can get\nthrough here, you\vcan go meet the\vELITE FOUR!",
  _VictoryRoad2FSuperNerd2EndBattleText = "No!\nUnbelievable!",
  _VictoryRoad2FSuperNerd3AfterBattleText = "Many trainers give\nup the challenge\vhere.",
  _VictoryRoad2FSuperNerd3BattleText = "Is VICTORY ROAD\ntoo tough?",
  _VictoryRoad2FSuperNerd3EndBattleText = "Well\ndone!",
  _VictoryRoad3FCooltrainerF1AfterBattleText = "You showed me just\nhow good I was!",
  _VictoryRoad3FCooltrainerF1BattleText = "I'll show you just\nhow good you are!",
  _VictoryRoad3FCooltrainerF1EndBattleText = "I'm\nfurious!",
  _VictoryRoad3FCooltrainerF2AfterBattleText = "By fighting tough\nbattles, you get\vstronger!",
  _VictoryRoad3FCooltrainerF2BattleText = "Trainers live to\nseek stronger\vopponents!",
  _VictoryRoad3FCooltrainerF2EndBattleText = "Oh!\nSo strong!",
  _VictoryRoad3FCooltrainerM1AfterBattleText = "You beat GIOVANNI\nof TEAM ROCKET?",
  _VictoryRoad3FCooltrainerM1BattleText = "I heard rumors of\na child prodigy!",
  _VictoryRoad3FCooltrainerM1EndBattleText = "The\nrumors were true!",
  _VictoryRoad3FCooltrainerM2AfterBattleText = "All trainers here\nare headed to the\vPOKéMON LEAGUE!\vBe careful!",
  _VictoryRoad3FCooltrainerM2BattleText = "Only the chosen\ncan pass here!",
  _VictoryRoad3FCooltrainerM2EndBattleText = "I\ndon't believe it!",
  _VictreebelDexEntry = "Said to live in\nhuge colonies\ndeep in jungles,\falthough no one\nhas ever returned\nfrom there",
  _VileplumeDexEntry = "The larger its\npetals, the more\ntoxic pollen it\fcontains. Its big\nhead is heavy and\nhard to hold up",
  _ViridianBlackboardBurnText = "A burn reduces\npower and speed.\vIt also causes\vongoing damage.\fBurns remain\nafter battles.\fUse BURN HEAL to\ncure a burn!",
  _ViridianBlackboardFrozenText = "If frozen, a\nPOKéMON becomes\vtotally immobile!\fIt stays frozen\neven after the\vbattle ends.\fUse ICE HEAL to\nthaw out POKéMON!",
  _ViridianBlackboardPoisonText = "When poisoned, a\nPOKéMON's health\vsteadily drops.\fPoison lingers\nafter battles.\fUse an ANTIDOTE\nto cure poison!",
  _ViridianBlackboardPrlzText = "Paralysis could\nmake POKéMON\vmoves misfire!\fParalysis remains\nafter battles.\fUse PARLYZ HEAL\nfor treatment!",
  _ViridianBlackboardSleepText = "A POKéMON can't\nattack if it's\vasleep!\fPOKéMON will stay\nasleep even after\vbattles.\fUse AWAKENING to\nwake them up!",
  _ViridianCityFisherReceivedTM42Text = "{PLAYER} received\nTM42!",
  _ViridianCityFisherTM42ExplanationText = "TM42 contains\nDREAM EATER...\v...Snore...",
  _ViridianCityFisherTM42NoRoomText = "You have too much\nstuff already.",
  _ViridianCityGambler1GymAlwaysClosedText = "This POKéMON GYM\nis always closed.\fI wonder who the\nLEADER is?",
  _ViridianCityGambler1GymLeaderReturnedText = "VIRIDIAN GYM's\nLEADER returned!",
  _ViridianCityGirlHasntHadHisCoffeeYetText = "Oh Grandpa! Don't\nbe so mean!\vHe hasn't had his\vcoffee yet.",
  _ViridianCityGirlWhenIGoShopText = "When I go shop in\nPEWTER CITY, I\vhave to take the\vwinding trail in\vVIRIDIAN FOREST.",
  _ViridianCityGymLockedText = "The GYM's doors\nare locked...",
  _ViridianCityGymSignText = "VIRIDIAN CITY\nPOKéMON GYM",
  _ViridianCityOldManHadMyCoffeeNowText = "Ahh, I've had my\ncoffee now and I\vfeel great!\fSure you can go\nthrough!\fAre you in a\nhurry?",
  _ViridianCityOldManKnowHowToCatchPokemonText = "I see you're using\na POKéDEX.\fWhen you catch a\nPOKéMON, POKéDEX\vis automatically\vupdated.\fWhat? Don't you\nknow how to catch\vPOKéMON?\fI'll show you\nhow to then.",
  _ViridianCityOldManSleepyPrivatePropertyText = "You can't go\nthrough here!\fThis is private\nproperty!",
  _ViridianCityOldManTimeIsMoneyText = "Time is money...\nGo along then.",
  _ViridianCityOldManYouNeedToWeakenTheTargetText = "First, you need\nto weaken the\vtarget POKéMON.",
  _ViridianCityPokecenterGuyText = "POKéMON CENTERs\nheal your tired,\vhurt or fainted\vPOKéMON!",
  _ViridianCitySignText = "VIRIDIAN CITY \nThe Eternally\vGreen Paradise",
  _ViridianCityTrainerTips1Text = "TRAINER TIPS\fCatch POKéMON\nand expand your\vcollection!\fThe more you have,\nthe easier it is\vto fight!",
  _ViridianCityTrainerTips2Text = "TRAINER TIPS\fThe battle moves\nof POKéMON are\vlimited by their\vPOWER POINTs, PP.\fTo replenish PP,\nrest your tired\vPOKéMON at a\vPOKéMON CENTER!",
  _ViridianCityYoungster1Text = "Those POKé BALLs\nat your waist!\vYou have POKéMON!\fIt's great that\nyou can carry and\vuse POKéMON any\vtime, anywhere!",
  _ViridianCityYoungster2YouWantToKnowAboutText = "You want to know\nabout the 2 kinds\vof caterpillar\vPOKéMON?",
  _ViridianForestLeavingSignText = "LEAVING\nVIRIDIAN FOREST\vPEWTER CITY AHEAD",
  _ViridianForestNorthGateGrampsText = "Have you noticed\nthe bushes on the\vroadside?\fThey can be cut\ndown by a special\vPOKéMON move.",
  _ViridianForestNorthGateSuperNerdText = "Many POKéMON live\nonly in forests \vand caves.\fYou need to look\neverywhere to get\vdifferent kinds!",
  _ViridianForestSouthGateGirlText = "Are you going to\nVIRIDIAN FOREST?\vBe careful, it's\va natural maze!",
  _ViridianForestSouthGateLittleGirlText = "RATTATA may be\nsmall, but its\vbite is wicked!\vDid you get one?",
  _ViridianForestTrainerTips1Text = "TRAINER TIPS\fIf you want to\navoid battles,\vstay away from\vgrassy areas!",
  _ViridianForestTrainerTips2Text = "TRAINER TIPS\fContact PROF.OAK\nvia PC to get\vyour POKéDEX\vevaluated!",
  _ViridianForestTrainerTips3Text = "TRAINER TIPS\fNo stealing of\nPOKéMON from\vother trainers!\vCatch only wild\vPOKéMON!",
  _ViridianForestTrainerTips4Text = "TRAINER TIPS\fWeaken POKéMON\nbefore attempting\vcapture!\fWhen healthy,\nthey may escape!",
  _ViridianForestUseAntidoteSignText = "For poison, use\nANTIDOTE! Get it\vat POKéMON MARTs!",
  _ViridianForestYoungster1Text = "I came here with\nsome friends!\fThey're out for\nPOKéMON fights!",
  _ViridianForestYoungster2AfterBattleText = "Ssh! You'll scare\nthe bugs away!",
  _ViridianForestYoungster2BattleText = "Hey! You have\nPOKéMON! Come on!\vLet's battle'em!",
  _ViridianForestYoungster2EndBattleText = "No!\nCATERPIE can't\vcut it!",
  _ViridianForestYoungster3AfterBattleText = "Darn! I'm going\nto catch some\vstronger ones!",
  _ViridianForestYoungster3BattleText = "Yo! You can't jam\nout if you're a\vPOKéMON trainer!",
  _ViridianForestYoungster3EndBattleText = "Huh?\nI ran out of\vPOKéMON!",
  _ViridianForestYoungster4AfterBattleText = "Sometimes, you\ncan find stuff on\vthe ground!\fI'm looking for\nthe stuff I\vdropped!",
  _ViridianForestYoungster4BattleText = "Hey, wait up!\nWhat's the hurry?",
  _ViridianForestYoungster4EndBattleText = "I\ngive! You're good\vat this!",
  _ViridianForestYoungster5Text = "I ran out of POKé\nBALLs to catch\vPOKéMON with!\fYou should carry\nextras!",
  _ViridianGymCooltrainerM1AfterBattleText = "You need power to\nkeep up with our\vGYM LEADER!",
  _ViridianGymCooltrainerM1BattleText = "Heh! You must be\nrunning out of\vsteam by now!",
  _ViridianGymCooltrainerM1EndBattleText = "I\nran out of gas!",
  _ViridianGymCooltrainerM2AfterBattleText = "The LEADER will\nscold me!",
  _ViridianGymCooltrainerM2BattleText = "The truly talented\nwin with style!",
  _ViridianGymCooltrainerM2EndBattleText = "I\nlost my grip!",
  _ViridianGymCooltrainerM3AfterBattleText = "You can go onto\nPOKéMON LEAGUE\vonly by defeating\vour GYM LEADER!",
  _ViridianGymCooltrainerM3BattleText = "VIRIDIAN GYM was\nclosed for a long\vtime, but now our\vLEADER is back!",
  _ViridianGymCooltrainerM3EndBattleText = "I\nwas beaten?",
  _ViridianGymGiovanniEarthBadgeInfoText = "The EARTHBADGE\nmakes POKéMON of\vany level obey!\fIt is evidence of\nyour mastery as a\vPOKéMON trainer!\fWith it, you can\nenter the POKéMON\vLEAGUE!\fIt is my gift for\nyour POKéMON\vLEAGUE challenge!",
  _ViridianGymGiovanniPostBattleAdviceText = "Having lost, I\ncannot face my\vunderlings!\vTEAM ROCKET is\vfinished forever!\fI will dedicate my\nlife to the study\vof POKéMON!\fLet us meet again\nsome day!\vFarewell!",
  _ViridianGymGiovanniPreBattleText = "Fwahahaha! This is\nmy hideout!\fI planned to\nresurrect TEAM\vROCKET here!\fBut, you have\ncaught me again!\vSo be it! This\vtime, I'm not\vholding back!\fOnce more, you\nshall face\vGIOVANNI, the\vgreatest trainer!",
  _ViridianGymGiovanniReceivedEarthBadgeText = "Ha!\nThat was a truly\vintense fight!\vYou have won!\vAs proof, here is\vthe EARTHBADGE!",
  _ViridianGymGiovanniReceivedTM27Text = "{PLAYER} received\nTM27!",
  _ViridianGymGiovanniTM27ExplanationText = "\fTM27 is FISSURE!\nIt will take out\vPOKéMON with just\vone hit!\fI made it when I\nran the GYM here,\vtoo long ago...",
  _ViridianGymGiovanniTM27NoRoomText = "You do not have\nspace for this!",
  _ViridianGymGuidePostBattleText = "Blow me away!\nGIOVANNI was the\vGYM LEADER here?",
  _ViridianGymGuidePreBattleText = "Yo! Champ in\nmaking!\fEven I don't know\nVIRIDIAN LEADER's\videntity!\fThis will be the\ntoughest of all\vthe GYM LEADERs!\fI heard that the\ntrainers here\vlike ground-type\vPOKéMON!",
  _ViridianGymHiker1AfterBattleText = "I'm still not\nworthy!",
  _ViridianGymHiker1BattleText = "Rrrroar! I'm\nworking myself\vinto a rage!",
  _ViridianGymHiker1EndBattleText = "Wargh!",
  _ViridianGymHiker2AfterBattleText = "If my POKéMON\nwere as good at\vKarate as I...",
  _ViridianGymHiker2BattleText = "Karate is the\nultimate form of\vmartial arts!",
  _ViridianGymHiker2EndBattleText = "Atcho!",
  _ViridianGymHiker3AfterBattleText = "POKéMON LEAGUE?\nYou? Don't get\vcocky!",
  _ViridianGymHiker3BattleText = "I'm the KARATE\nKING! Your fate\vrests with me!",
  _ViridianGymHiker3EndBattleText = "Ayah!",
  _ViridianGymRocker1AfterBattleText = "Do you know the\nidentity of our\vGYM LEADER?",
  _ViridianGymRocker1BattleText = "POKéMON and I, we\nmake wonderful\vmusic together!",
  _ViridianGymRocker1EndBattleText = "You are in\nperfect harmony!",
  _ViridianGymRocker2AfterBattleText = "Wait! I was just\ncareless!",
  _ViridianGymRocker2BattleText = "Your POKéMON will\ncower at the\vcrack of my whip!",
  _ViridianGymRocker2EndBattleText = "Yowch!\nWhiplash!",
  _ViridianMartClerkParcelQuestText = "You know PROF.\nOAK, right?\fHis order came in.\nWill you take it\vto him?\f{PLAYER} got\nOAK's PARCEL!",
  _ViridianMartClerkSayHiToOakText = "Okay! Say hi to\nPROF.OAK for me!",
  _ViridianMartClerkYouCameFromPalletTownText = "Hey! You came from\nPALLET TOWN?",
  _ViridianMartCooltrainerMText = "No! POTIONs are\nall sold out.",
  _ViridianMartYoungsterText = "This shop sells\nmany ANTIDOTEs.",
  _ViridianNicknameHouseBaldingGuyText = "Coming up with\nnicknames is fun,\vbut hard.\fSimple names are\nthe easiest to\vremember.",
  _ViridianNicknameHouseLittleGirlText = "My Daddy loves\nPOKéMON too.",
